<template>
  <section
    class="page-video min-w-0 w-full rounded border border-border bg-card p-3 text-foreground"
    data-test="page-video-card"
  >
    <template v-if="validated">
      <video
        ref="player"
        class="aspect-video w-full"
        controls
        playsinline
        preload="none"
        :poster="validated.assets.poster.url"
        :src="validated.assets.mp4.url"
        :aria-label="validated.title"
        @error="failed = true"
        @loadedmetadata="showCaptions"
      >
        <track
          v-if="captionUrl"
          :key="captionUrl"
          :src="captionUrl"
          kind="captions"
          :srclang="validated.caption_locale"
          :label="captionLabel"
          default
          @load="showCaptions"
        />
      </video>
      <p class="mt-2 font-semibold">{{ validated.title }}</p>
      <p
        v-if="validated.audio_mode === 'english_fallback'"
        class="text-sm text-muted-foreground"
      >
        {{ $t('settings_assistant.video.english_audio') }}
      </p>
      <p
        v-if="validated.locale !== uiVideoLocale"
        class="text-sm text-muted-foreground"
      >
        <!-- Props form, not $t(key, { language }): Tolgee reads `language`
             (like ns/noWrap/orEmpty/params) in the second argument as the
             translation-language option, so the placeholder never got its
             value and Tolgee threw "Missing parameter" (CORE-6323). -->
        {{
          $t({
            key: 'settings_assistant.video.language',
            params: { language: languageName },
          })
        }}
      </p>
      <div v-if="failed" role="status">
        <p>{{ $t('settings_assistant.video.playback_error') }}</p>
        <q-btn
          class="f-btn"
          flat
          :label="$t('settings_assistant.video.retry')"
          @click="retryPlayback"
        />
      </div>
      <q-btn
        class="f-btn mt-2"
        flat
        :aria-expanded="transcriptOpen"
        :label="
          $t(
            transcriptOpen
              ? 'settings_assistant.video.hide_transcript'
              : 'settings_assistant.video.show_transcript',
          )
        "
        @click="transcriptOpen = !transcriptOpen"
      />
      <div
        v-if="transcriptOpen"
        class="mt-2 whitespace-pre-wrap break-words"
        :aria-label="$t('settings_assistant.video.transcript')"
      >
        {{ validated.transcript }}
      </div>
    </template>
    <p v-else>{{ $t('settings_assistant.video.unavailable') }}</p>
  </section>
</template>
<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import {
  parsePageVideo,
  resolveVideoLocale,
  videoLanguageName,
  videoVtt,
  type PageVideo,
} from 'src/utils/settingsAssistant/pageVideos';
export default defineComponent({
  name: 'SettingsAssistantPageVideoCard',
  props: {
    video: { type: Object as PropType<PageVideo>, required: true },
    uiLocale: { type: String, default: 'en' },
  },
  data() {
    return { captionUrl: '', failed: false, transcriptOpen: false };
  },
  computed: {
    validated(): PageVideo | null {
      return parsePageVideo(this.video);
    },
    uiVideoLocale(): string {
      return resolveVideoLocale(this.uiLocale);
    },
    languageName(): string {
      return videoLanguageName(this.validated?.locale || 'en');
    },
    captionLabel(): string {
      return `${this.$t('settings_assistant.video.captions')} — ${this.languageName}`;
    },
  },
  watch: {
    video: {
      handler() {
        this.replaceVideo();
      },
      deep: true,
      flush: 'pre',
    },
  },
  mounted() {
    this.replaceVideo();
  },
  beforeUnmount() {
    this.cleanup();
  },
  methods: {
    cleanup() {
      const player = this.$refs.player as HTMLVideoElement | undefined;
      if (player) {
        player.pause();
        player.removeAttribute('src');
        player.querySelector('track')?.removeAttribute('src');
        player.load();
      }
      if (this.captionUrl) URL.revokeObjectURL(this.captionUrl);
      this.captionUrl = '';
    },
    replaceVideo() {
      this.cleanup();
      this.failed = false;
      if (!this.validated) return;
      this.captionUrl = URL.createObjectURL(
        new Blob([videoVtt(this.validated)], { type: 'text/vtt' }),
      );
      this.$nextTick(() => {
        const player = this.$refs.player as HTMLVideoElement | undefined;
        if (player && this.validated)
          player.src = this.validated.assets.mp4.url;
        this.showCaptions();
      });
    },
    showCaptions() {
      const player = this.$refs.player as HTMLVideoElement | undefined;
      if (player?.textTracks?.[0]) player.textTracks[0].mode = 'showing';
    },
    retryPlayback() {
      this.failed = false;
      (this.$refs.player as HTMLVideoElement | undefined)?.load();
    },
  },
});
</script>
<style scoped>
.page-video :focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 2px;
}
</style>
