/**
 * CORE-6145 — the `import_actions` chunk of the Settings Assistant stream: one
 * offer per import connection (email mailbox or FTP/SFTP) that stopped working,
 * built by doc2-api from the config-check findings (never by the model).
 *
 * A payload is only rendered when each item carries what the card and the
 * preview call need; anything else is dropped, never half-drawn.
 */
export type ImportChannel = 'email' | 'ftp';

export interface ImportActionOffer {
  channel: ImportChannel;
  /** int text for a mailbox, UUID text for an FTP connection. */
  config_id: string;
  /** The address / host; null = a mailbox saved without an address. */
  label: string | null;
  switched_off: boolean;
  /** CORE-6319: when it was switched off (ISO 8601), as the import service
   * recorded it; null when not recorded. */
  switched_off_on: string | null;
  /** CORE-6319: who switched it off (display name); null when not recorded. */
  switched_off_by_name: string | null;
  failed_attempts: number;
  /** One of the fixed reason codes (auth_rejected, unreachable, ...). */
  reason_code: string;
  /** A wrong/invalid credential: the useful question is "do you have it?". */
  asks_for_credentials: boolean;
  can_deactivate: boolean;
  can_delete: boolean;
}

const KNOWN_REASON_CODES = [
  'auth_policy',
  'auth_rejected',
  'not_found',
  'unreachable',
  'timeout',
  'tls',
  'unknown',
  // CORE-6319: switched off without failures - the card says when and by
  // whom (or that it is not recorded), never "reason could not be determined".
  'switched_off',
];

/** Date format when the user has no date preference (de/en: DD.MM.YYYY). */
export const DEFAULT_SWITCHED_OFF_DATE_FORMAT = 'DD.MM.YYYY';

/** The recorded switch-off day in ``pattern`` (a Quasar date format, the
 * user's preference) or DD.MM.YYYY; null for a missing or invalid value. */
export function formatSwitchedOffDate(
  value: string | null,
  pattern?: string | null,
): string | null {
  if (!value) return null;
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) return null;
  const format = pattern?.trim() || DEFAULT_SWITCHED_OFF_DATE_FORMAT;
  // A calendar day only (local to the viewer): YYYY, YY, MM, M, DD, D; any
  // other text in the pattern is kept as written.
  const parts: Record<string, string> = {
    YYYY: String(parsed.getFullYear()),
    YY: String(parsed.getFullYear()).slice(-2),
    MM: String(parsed.getMonth() + 1).padStart(2, '0'),
    M: String(parsed.getMonth() + 1),
    DD: String(parsed.getDate()).padStart(2, '0'),
    D: String(parsed.getDate()),
  };
  return format.replace(/YYYY|YY|MM|M|DD|D/g, (token) => parts[token]);
}

/** The i18n key and params of a switched-off connection's "Deactivated ..."
 * line: with date and name only when BOTH are recorded, otherwise the
 * "details not available" text. Nothing is ever guessed. */
export function switchedOffText(
  offer: Pick<ImportActionOffer, 'switched_off_on' | 'switched_off_by_name'>,
  pattern?: string | null,
): { key: string; params: Record<string, string> } {
  const day = formatSwitchedOffDate(offer.switched_off_on, pattern);
  if (day && offer.switched_off_by_name) {
    return {
      key: 'settings_assistant_health_switched_off_on_by',
      params: { date: day, name: offer.switched_off_by_name },
    };
  }
  return {
    key: 'settings_assistant_health_switched_off_no_details',
    params: {},
  };
}

function validDateText(value: unknown): string | null {
  if (typeof value !== 'string' || !value.trim()) return null;
  return Number.isNaN(new Date(value).getTime()) ? null : value;
}

/** i18n key for a reason code; a code this build does not know shows the
 * `unknown` text (no raw code and no backend text is ever printed). */
export function reasonKeyFor(code: unknown): string {
  // No reason is recorded for a plain switch-off; its card states when and by
  // whom instead (switchedOffText). Without those details this is the text.
  if (code === 'switched_off') {
    return 'settings_assistant_health_switched_off_no_details';
  }
  const known = KNOWN_REASON_CODES.includes(code as string) ? code : 'unknown';
  return `settings_assistant_health_reason_${known}`;
}

function toOffer(value: unknown): ImportActionOffer | null {
  if (!value || typeof value !== 'object') return null;
  const v = value as Record<string, unknown>;
  if (v.channel !== 'email' && v.channel !== 'ftp') return null;
  if (typeof v.config_id !== 'string' || !v.config_id) return null;
  if (typeof v.switched_off !== 'boolean') return null;
  const failures = Number(v.failed_attempts);
  return {
    channel: v.channel,
    config_id: v.config_id,
    label: typeof v.label === 'string' && v.label ? v.label : null,
    switched_off: v.switched_off,
    switched_off_on: v.switched_off ? validDateText(v.switched_off_on) : null,
    switched_off_by_name:
      v.switched_off &&
      typeof v.switched_off_by_name === 'string' &&
      v.switched_off_by_name.trim()
        ? v.switched_off_by_name.trim()
        : null,
    failed_attempts: Number.isFinite(failures)
      ? Math.max(0, Math.trunc(failures))
      : 0,
    reason_code: typeof v.reason_code === 'string' ? v.reason_code : 'unknown',
    asks_for_credentials: v.asks_for_credentials === true,
    can_deactivate: v.can_deactivate === true,
    can_delete: v.can_delete === true,
  };
}

/** The valid offers of a chunk's `items`; `[]` for anything that is not a list. */
export function parseImportActionOffers(items: unknown): ImportActionOffer[] {
  if (!Array.isArray(items)) return [];
  return items.map(toOffer).filter((o): o is ImportActionOffer => o !== null);
}
