<template>
  <!--
    CORE-6145 — proactive notice: an email or FTP import this org has set up
    has stopped working. Shown above the greeting without the admin asking;
    renders nothing for orgs without such a channel, for non-admins (403)
    and on any error. Text is built from rule_id + measured_value here, never
    from the backend's English-only `message`, and never as HTML.
    CORE-6148 — ONE card per channel (email, FTP) with a collapsible list of
    the affected configurations, so none of them is hidden behind a cap.
  -->
  <!-- One persistent live region holding ONLY a short announcement, so
       expanding a list or flipping a button label never re-announces cards.
       It is always visually hidden (see the style) and adds no gap; the
       interactive cards are a separate sibling outside any live region. -->
  <div
    class="sa-health-notice"
    role="status"
    aria-live="polite"
    data-test="settings-assistant-health-notice"
  >
    {{ announcement }}
  </div>
  <!-- Result of a confirmed change. Outside the cards on purpose: deleting the
       last mailbox removes its card, and the undo must stay reachable. -->
  <div
    v-if="done"
    class="sa-health-notice__done"
    role="status"
    data-test="settings-assistant-health-notice-done"
  >
    <span data-test="settings-assistant-health-notice-done-text">{{
      doneText
    }}</span>
    <button
      v-if="done.undoId"
      type="button"
      class="sa-health-notice__btn"
      :disabled="busy"
      data-test="settings-assistant-health-notice-undo"
      @click="undoAction"
    >
      {{ $t('settings_assistant_health_action_undo') }}
    </button>
  </div>
  <p
    v-if="actionError && actionError.configId === ''"
    class="sa-health-notice__action-error"
    role="alert"
    data-test="settings-assistant-health-notice-global-error"
  >
    {{ $t(actionError.key) }}
  </p>
  <div v-if="visibleCards.length" class="sa-health-notice__list">
    <div
      v-for="card in visibleCards"
      :key="card.channel"
      class="sa-health-notice__card"
      :class="{ 'sa-health-notice__card--off': card.offCount > 0 }"
      :data-channel="card.channel"
      data-test="settings-assistant-health-notice-card"
    >
      <button
        type="button"
        class="sa-health-notice__close"
        :aria-label="$t('close')"
        :title="$t('close')"
        data-test="settings-assistant-health-notice-dismiss"
        @click="dismiss(card)"
      >
        <Icon icon="mdi:close" width="16" height="16" />
      </button>
      <div class="sa-health-notice__title">
        <Icon
          :icon="card.icon"
          width="18"
          height="18"
          class="sa-health-notice__icon shrink-0"
        />
        <span data-test="settings-assistant-health-notice-title">{{
          cardTitle(card)
        }}</span>
      </div>
      <p
        class="sa-health-notice__text"
        data-test="settings-assistant-health-notice-summary"
      >
        {{ summary(card) }}
        {{
          $t('settings_assistant_health_summary_worst', {
            config: card.worst.config,
            count: card.worst.count,
          })
        }}
      </p>
      <ul
        v-show="expanded[card.channel]"
        :id="detailsId(card.channel)"
        class="sa-health-notice__rows"
        data-test="settings-assistant-health-notice-rows"
      >
        <li
          v-for="(row, idx) in card.rows.slice(0, MAX_ROWS)"
          :key="`${row.configId}-${row.config}-${idx}`"
          class="sa-health-notice__row"
          data-test="settings-assistant-health-notice-row"
        >
          <div class="sa-health-notice__row-head">
            <span class="sa-health-notice__config">{{ row.config }}</span>
            <span
              class="sa-health-notice__badge"
              :class="{ 'sa-health-notice__badge--off': row.switchedOff }"
            >
              {{
                $t(
                  row.switchedOff
                    ? 'settings_assistant_health_row_off'
                    : 'settings_assistant_health_row_retrying',
                )
              }}
            </span>
            <span class="sa-health-notice__failures">
              {{
                $t(
                  row.count === 1
                    ? 'settings_assistant_health_row_failures_one'
                    : 'settings_assistant_health_row_failures_other',
                  { count: row.count },
                )
              }}
            </span>
          </div>
          <div
            v-if="row.reasonKey"
            class="sa-health-notice__reason"
            data-test="settings-assistant-health-notice-reason"
          >
            {{ $t(row.reasonKey) }}
          </div>
          <div
            v-if="canAct(card, row)"
            class="sa-health-notice__row-actions"
            data-test="settings-assistant-health-notice-row-actions"
          >
            <div
              v-if="pending && pending.configId === row.configId"
              class="sa-health-notice__confirm"
              role="group"
              :aria-label="confirmText"
              data-test="settings-assistant-health-notice-confirm"
            >
              <p
                class="sa-health-notice__confirm-text"
                data-test="settings-assistant-health-notice-confirm-text"
              >
                {{ confirmText }}
              </p>
              <div class="sa-health-notice__actions">
                <button
                  type="button"
                  class="sa-health-notice__btn"
                  :class="
                    pending.action === 'delete'
                      ? 'sa-health-notice__btn--danger'
                      : 'sa-health-notice__btn--primary'
                  "
                  :disabled="busy"
                  data-test="settings-assistant-health-notice-confirm-yes"
                  @click="confirmAction"
                >
                  {{
                    $t(
                      pending.action === 'delete'
                        ? 'settings_assistant_health_action_confirm_delete_yes'
                        : 'settings_assistant_health_action_confirm_deactivate_yes',
                    )
                  }}
                </button>
                <button
                  type="button"
                  class="sa-health-notice__btn"
                  :disabled="busy"
                  data-test="settings-assistant-health-notice-confirm-cancel"
                  @click="cancelAction"
                >
                  {{ $t('settings_assistant_health_action_cancel') }}
                </button>
              </div>
            </div>
            <div v-else class="sa-health-notice__actions">
              <button
                v-if="!row.switchedOff"
                type="button"
                class="sa-health-notice__btn"
                :disabled="busy"
                data-test="settings-assistant-health-notice-deactivate"
                @click="startAction(row, 'deactivate', card.channel)"
              >
                {{ $t('settings_assistant_health_action_deactivate') }}
              </button>
              <button
                type="button"
                class="sa-health-notice__btn sa-health-notice__btn--danger-outline"
                :disabled="busy"
                data-test="settings-assistant-health-notice-delete"
                @click="startAction(row, 'delete', card.channel)"
              >
                {{ $t('settings_assistant_health_action_delete') }}
              </button>
            </div>
            <p
              v-if="actionError && actionError.configId === row.configId"
              class="sa-health-notice__action-error"
              role="alert"
              data-test="settings-assistant-health-notice-action-error"
            >
              {{ $t(actionError.key) }}
            </p>
          </div>
        </li>
        <li
          v-if="card.rows.length > MAX_ROWS"
          class="sa-health-notice__more"
          data-test="settings-assistant-health-notice-more"
        >
          {{
            $t('settings_assistant_health_more', {
              count: card.rows.length - MAX_ROWS,
            })
          }}
        </li>
      </ul>
      <div class="sa-health-notice__actions">
        <button
          type="button"
          class="sa-health-notice__btn"
          :aria-expanded="expanded[card.channel] ? 'true' : 'false'"
          :aria-controls="detailsId(card.channel)"
          data-test="settings-assistant-health-notice-toggle"
          @click="toggle(card.channel)"
        >
          {{
            $t(
              expanded[card.channel]
                ? 'settings_assistant_health_hide_errors'
                : 'settings_assistant_health_show_errors',
            )
          }}
        </button>
        <button
          type="button"
          class="sa-health-notice__btn"
          data-test="settings-assistant-health-notice-open-settings"
          @click="openSettings"
        >
          {{ $t('settings_assistant_health_open_settings') }}
        </button>
        <button
          type="button"
          class="sa-health-notice__btn sa-health-notice__btn--primary"
          data-test="settings-assistant-health-notice-help"
          @click="$emit('ask', $t(card.questionKey))"
        >
          {{ $t('settings_assistant_health_help') }}
        </button>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { Icon } from '@iconify/vue';
// Direct file import, NOT the src/generated-api-sdk barrel (CLAUDE.md's
// barrel-import rule).
import { SettingsAssistantService } from 'src/generated-api-sdk/services/SettingsAssistantService';
import { logger } from 'src/utils/logger';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import { ApplyRequestError } from 'src/services/settingsAssistant/settingsAssistantApplyService';
import {
  settingsAssistantImportEmailService,
  type ImportEmailAction,
} from 'src/services/settingsAssistant/settingsAssistantImportEmailService';

const IMPORT_SETTINGS_PATH = '/settings/import';
const MAX_ROWS = 10;

/** reason_code values the API may send. Anything else (a newer API) shows the
 * `unknown` label: no raw code and no backend text is ever printed. */
const REASON_CODES = [
  'auth_policy',
  'auth_rejected',
  'not_found',
  'unreachable',
  'timeout',
  'tls',
  'unknown',
];
function reasonKeyFor(code: unknown): string {
  if (code === null || code === undefined || code === '') return '';
  const known = REASON_CODES.includes(code as string) ? code : 'unknown';
  return `settings_assistant_health_reason_${known}`;
}

type Channel = 'email' | 'ftp';

/** The two config-check rules this notice reports on, and everything that
 * differs per channel. The FTP service counts every failed import, not only
 * rejected logins. Plural forms are separate keys (FormatSimple has no ICU
 * plural). */
const CHANNELS: Record<
  Channel,
  {
    ruleId: string;
    icon: string;
    titleOneKey: string;
    titleOtherKey: string;
    questionKey: string;
  }
> = {
  email: {
    ruleId: 'email_import_auth_failures',
    icon: 'mdi:email-alert-outline',
    titleOneKey: 'settings_assistant_health_email_title_one',
    titleOtherKey: 'settings_assistant_health_email_title_other',
    questionKey: 'settings_assistant_health_email_question',
  },
  ftp: {
    ruleId: 'ftp_import_auth_failures',
    icon: 'mdi:lan-disconnect',
    titleOneKey: 'settings_assistant_health_ftp_title_one',
    titleOtherKey: 'settings_assistant_health_ftp_title_other',
    questionKey: 'settings_assistant_health_ftp_question',
  },
};
const CHANNEL_ORDER: Channel[] = ['email', 'ftp'];
const CHANNEL_BY_RULE: Record<string, Channel> = {
  email_import_auth_failures: 'email',
  ftp_import_auth_failures: 'ftp',
};

/** A failure count as a finite whole number: non-numeric, NaN, ±Infinity and
 * negative values are 0 (JSON would otherwise encode ±Infinity as null). */
function toCount(value: unknown): number {
  const n = Number(value);
  return Number.isFinite(n) ? Math.max(0, Math.trunc(n)) : 0;
}

interface HealthRow {
  config: string;
  configId: string;
  count: number;
  switchedOff: boolean;
  /** i18n key for the reason code, '' when the API sent none. */
  reasonKey: string;
}

/** Compact, unambiguous fingerprint of what the cards show: JSON over the
 * rows in a total order, so no value can bleed into its neighbour. */
function signature(cards: HealthCard[]): string {
  const rows = cards.flatMap((c) =>
    c.rows.map((r) => [
      c.channel,
      r.configId,
      r.config,
      r.switchedOff ? 1 : 0,
      r.count,
      r.reasonKey,
    ]),
  );
  rows.sort((x, y) => {
    for (let i = 0; i < x.length; i++) {
      if (x[i] < y[i]) return -1;
      if (x[i] > y[i]) return 1;
    }
    return 0;
  });
  return JSON.stringify(rows);
}

interface HealthCard {
  channel: Channel;
  icon: string;
  titleOneKey: string;
  titleOtherKey: string;
  questionKey: string;
  count: number;
  offCount: number;
  retryingCount: number;
  worst: HealthRow;
  rows: HealthRow[];
}

interface PendingAction {
  configId: string;
  channel: Channel;
  action: ImportEmailAction;
  previewId: string;
  label: string;
  server: string;
}

interface DoneAction {
  action: ImportEmailAction;
  /** null for a delete: nothing to undo. */
  undoId: string | null;
  label: string;
}

export default defineComponent({
  name: 'SettingsAssistantHealthNotice',

  components: { Icon },

  emits: ['open-settings', 'ask', 'dismissed'],

  data() {
    return {
      cards: [] as HealthCard[],
      expanded: {} as Record<string, boolean>,
      MAX_ROWS,
      /** Bumped per request; a response only counts while it is the latest. */
      requestSeq: 0,
      loadedOrgId: '',
      /** Switch-off / delete: the previewed change awaiting the admin's yes. */
      pending: null as PendingAction | null,
      /** The last confirmed change, kept so it can be undone. */
      done: null as DoneAction | null,
      actionError: null as { configId: string; key: string } | null,
      busy: false,
      /** channel -> fingerprint of the card the admin closed. The card stays
       * hidden until its findings change. */
      dismissed: {} as Record<string, string>,
    };
  },

  mounted() {
    this.load();
    // Org switching (OrgPicker / crossTabSessionSync) writes storage and then
    // hard-navigates or reloads; there is no reactive org store. So the org is
    // re-read on every signal that can follow a switch: a route change, the
    // `storage` event another tab's switch raises, and the tab regaining
    // visibility.
    this.$watch(() => this.$route?.fullPath, this.syncOrg);
    window.addEventListener('storage', this.syncOrg);
    document.addEventListener('visibilitychange', this.onVisibilityChange);
  },

  beforeUnmount() {
    // An in-flight response must not assign after unmount.
    this.requestSeq += 1;
    window.removeEventListener('storage', this.syncOrg);
    document.removeEventListener('visibilitychange', this.onVisibilityChange);
  },

  computed: {
    /** Cards the admin has not closed (or whose findings changed since). */
    visibleCards(): HealthCard[] {
      return this.cards.filter(
        (c) => this.dismissed[c.channel] !== signature([c]),
      );
    },

    /** What the live region says: changes only when the findings change. */
    announcement(): string {
      return this.visibleCards.map((c) => this.cardTitle(c) + '.').join(' ');
    },

    confirmText(): string {
      const p = this.pending;
      if (!p) return '';
      return this.$t(
        p.action === 'delete'
          ? 'settings_assistant_health_action_confirm_delete'
          : 'settings_assistant_health_action_confirm_deactivate',
        { config: p.label, server: p.server },
      );
    },

    doneText(): string {
      const d = this.done;
      if (!d) return '';
      return this.$t(
        d.action === 'delete'
          ? 'settings_assistant_health_action_done_delete'
          : 'settings_assistant_health_action_done_deactivate',
        { config: d.label },
      );
    },
  },

  methods: {
    openSettings() {
      this.$emit('open-settings', IMPORT_SETTINGS_PATH);
    },

    onVisibilityChange() {
      if (document.visibilityState !== 'hidden') this.syncOrg();
    },

    /** The org changed under us: drop what is on screen (it belongs to the
     * previous org) BEFORE fetching for the new one. */
    syncOrg() {
      if (getOrgId() !== this.loadedOrgId) this.load();
    },

    async load() {
      const seq = ++this.requestSeq;
      const orgId = getOrgId();
      // Only an org switch drops what is on screen (it belongs to the previous
      // org). A same-org refetch keeps it until the answer arrives, so the
      // live region is not emptied and re-announced for an unchanged result.
      if (orgId !== this.loadedOrgId) {
        this.cards = [];
        this.expanded = {};
        // A previewed or undoable change belongs to the previous org.
        this.pending = null;
        this.done = null;
        this.actionError = null;
        this.dismissed = {};
      }
      this.loadedOrgId = orgId;
      try {
        const res =
          await SettingsAssistantService.readConfigChecksSettingsAssistantConfigChecksGet(
            { xOrgId: orgId },
          );
        // A late answer for a previous org (or an older request) is dropped.
        if (seq !== this.requestSeq || orgId !== getOrgId()) return;
        if (!Array.isArray(res?.findings)) {
          throw new TypeError('config_checks: malformed response');
        }
        const next = this.toCards(res.findings);
        // A dismissal only covers the findings it was made for. Once the card
        // is gone or shows something else, the incident is over: a later
        // identical finding is a new one and must not stay hidden.
        this.dismissed = Object.fromEntries(
          Object.entries(this.dismissed).filter(([ch, sig]) =>
            next.some((c) => c.channel === ch && signature([c]) === sig),
          ),
        );
        if (signature(next) !== signature(this.cards)) {
          this.cards = next;
          // A channel whose card is gone must not re-open when it returns.
          const open = { ...this.expanded };
          for (const ch of Object.keys(open)) {
            if (!next.some((c) => c.channel === ch)) delete open[ch];
          }
          this.expanded = open;
        }
      } catch (err) {
        if (seq !== this.requestSeq) return;
        this.cards = [];
        // 403 = not an org admin: expected, silent. Anything else is reported
        // (status / error class only — findings are customer data).
        const status = (err as { status?: number })?.status;
        if (status !== 403) {
          logger.error(
            '[SettingsAssistantHealthNotice]',
            'config_checks failed',
            {
              status,
              errorClass: (err as Error)?.constructor?.name,
            },
          );
        }
      }
    },

    cardTitle(card: HealthCard) {
      return this.$t(card.count === 1 ? card.titleOneKey : card.titleOtherKey, {
        count: card.count,
      });
    },

    dismiss(card: HealthCard) {
      // A confirmation or error that belongs to this card goes with it, so it
      // cannot reappear unannounced when the card returns.
      const ids = card.rows.map((r) => r.configId);
      if (this.pending && ids.includes(this.pending.configId)) {
        this.pending = null;
      }
      if (this.actionError && ids.includes(this.actionError.configId)) {
        this.actionError = null;
      }
      const idx = this.visibleCards.findIndex(
        (c) => c.channel === card.channel,
      );
      this.dismissed = { ...this.dismissed, [card.channel]: signature([card]) };
      // The focused X disappears with its card: keep keyboard users on the
      // page by moving focus to the next card's X, or hand it to the parent
      // when this was the last card.
      const remaining = this.visibleCards;
      if (!remaining.length) {
        this.$emit('dismissed');
        return;
      }
      const target = remaining[Math.min(idx, remaining.length - 1)];
      this.$nextTick(() => {
        const el = this.$el?.parentElement?.querySelector?.(
          `[data-channel="${target.channel}"] .sa-health-notice__close`,
        ) as HTMLElement | null;
        el?.focus();
      });
    },

    toggle(channel: Channel) {
      this.expanded = { ...this.expanded, [channel]: !this.expanded[channel] };
    },

    /** Email and FTP both have these actions (CORE-6145), and only for a row
     * the API identified. */
    canAct(card: HealthCard, row: HealthRow): boolean {
      return row.configId !== '';
    },

    /** A mailbox saved without an address is listed as "?" by the API. */
    rowLabel(row: HealthRow): string {
      return row.config && row.config !== '?'
        ? row.config
        : this.$t('settings_assistant_health_action_no_email');
    },

    /** 409 = the mailbox changed since the preview; anything else is generic.
     * Status / error class only is logged — configurations are customer data. */
    actionErrorKey(err: unknown): string {
      const status = (err as { status?: number })?.status;
      if (err instanceof ApplyRequestError && status === 409) {
        return 'settings_assistant_health_action_error_stale';
      }
      logger.error('[SettingsAssistantHealthNotice]', 'mailbox action failed', {
        status,
        errorClass: (err as Error)?.constructor?.name,
      });
      return 'settings_assistant_health_action_error';
    },

    /** Step 1: a dry run. Nothing changes until `confirmAction`. */
    async startAction(
      row: HealthRow,
      action: ImportEmailAction,
      channel: Channel = 'email',
    ) {
      if (this.busy) return;
      this.busy = true;
      this.actionError = null;
      this.pending = null;
      const orgId = getOrgId();
      try {
        const preview = await settingsAssistantImportEmailService.preview(
          // A mailbox id is an integer, an FTP connection's id a UUID.
          channel === 'ftp' ? row.configId : Number(row.configId),
          action,
          channel,
        );
        if (orgId !== getOrgId()) return;
        // The card was closed while the preview ran: nobody can see the
        // confirmation, so it must not be left armed.
        if (channel in this.dismissed) return;
        this.pending = {
          configId: row.configId,
          channel,
          action,
          previewId: preview.preview_id,
          label: this.rowLabel(row),
          server: preview.config?.server ?? '',
        };
      } catch (err) {
        if (orgId !== getOrgId()) return;
        this.actionError = {
          configId: row.configId,
          key: this.actionErrorKey(err),
        };
        this.reveal(channel);
      } finally {
        this.busy = false;
      }
    },

    /** An action failed inside a card the admin closed meanwhile: the error is
     * rendered in that card, so it has to be visible again. */
    reveal(channel: Channel) {
      if (!(channel in this.dismissed)) return;
      const { [channel]: _gone, ...rest } = this.dismissed;
      this.dismissed = rest;
    },

    cancelAction() {
      this.pending = null;
    },

    /** Step 2: runs only from the admin's own click on the confirm button. */
    async confirmAction() {
      const pending = this.pending;
      if (!pending || this.busy) return;
      this.busy = true;
      const orgId = getOrgId();
      try {
        const result = await settingsAssistantImportEmailService.confirm(
          pending.previewId,
        );
        if (orgId !== getOrgId()) return;
        this.pending = null;
        this.actionError = null;
        this.done = {
          action: pending.action,
          undoId: result.undo_id,
          label: pending.label,
        };
        await this.load();
      } catch (err) {
        if (orgId !== getOrgId()) return;
        this.pending = null;
        this.actionError = {
          configId: pending.configId,
          key: this.actionErrorKey(err),
        };
        this.reveal(pending.channel);
        // The row changed under us: show what it looks like now.
        if ((err as { status?: number })?.status === 409) await this.load();
      } finally {
        this.busy = false;
      }
    },

    async undoAction() {
      const done = this.done;
      if (!done?.undoId || this.busy) return;
      this.busy = true;
      const orgId = getOrgId();
      try {
        await settingsAssistantImportEmailService.undo(done.undoId);
        if (orgId !== getOrgId()) return;
        this.done = null;
        await this.load();
      } catch (err) {
        if (orgId !== getOrgId()) return;
        // The undo no longer applies (expired or changed again): drop it.
        this.done = null;
        this.actionError = {
          configId: '',
          key: this.actionErrorKey(err),
        };
      } finally {
        this.busy = false;
      }
    },

    detailsId(channel: Channel) {
      return `sa-health-details-${this.$.uid}-${channel}`;
    },

    summary(card: HealthCard) {
      if (card.retryingCount === 0) {
        return this.$t('settings_assistant_health_summary_all_off');
      }
      if (card.offCount === 0) {
        return this.$t('settings_assistant_health_summary_all_retrying');
      }
      return this.$t('settings_assistant_health_summary_mixed', {
        off: card.offCount,
        retrying: card.retryingCount,
      });
    },

    /** Group the findings per channel. `channel` is taken from the finding
     * when the API sends it, else derived from the rule id (older API). */
    toCards(raw: unknown): HealthCard[] {
      if (!Array.isArray(raw)) return [];
      const byChannel = new Map<Channel, HealthRow[]>();
      // Per channel: the same config_id twice is ONE configuration. Rows
      // without an id are never merged. The group keeps every source row so
      // the merge is independent of input order.
      const groups = new Map<string, { merged: HealthRow; src: HealthRow[] }>();
      for (const item of raw) {
        const ruleChannel = CHANNEL_BY_RULE[item?.rule_id];
        if (!ruleChannel) continue;
        const measured = item.measured_value ?? {};
        const channel: Channel =
          measured.channel === 'email' || measured.channel === 'ftp'
            ? measured.channel
            : ruleChannel;
        const row: HealthRow = {
          config: String(measured.config ?? ''),
          configId: String(measured.config_id ?? ''),
          count: toCount(measured.auth_failed_count),
          switchedOff: measured.switched_off === true,
          reasonKey: reasonKeyFor(measured.reason_code),
        };
        const rows = byChannel.get(channel) ?? [];
        byChannel.set(channel, rows);
        const key = `${channel}:${row.configId}`;
        const group = row.configId ? groups.get(key) : undefined;
        if (group) {
          group.src.push(row);
          continue;
        }
        if (row.configId) groups.set(key, { merged: row, src: [row] });
        rows.push(row);
      }
      for (const { merged, src } of groups.values()) {
        if (src.length < 2) continue;
        // state = any off, failures = max; the reason comes from the most
        // relevant row that has one: switched-off first, then most failures,
        // ties -> first seen.
        let best: HealthRow | null = null;
        for (const r of src) {
          if (!r.reasonKey) continue;
          if (
            !best ||
            (r.switchedOff && !best.switchedOff) ||
            (r.switchedOff === best.switchedOff && r.count > best.count)
          ) {
            best = r;
          }
        }
        const reasonKey = best?.reasonKey ?? '';
        merged.switchedOff = src.some((r) => r.switchedOff);
        merged.count = Math.max(...src.map((r) => r.count));
        merged.reasonKey = reasonKey;
      }
      const cards: HealthCard[] = [];
      for (const channel of CHANNEL_ORDER) {
        const found = byChannel.get(channel);
        if (!found?.length) continue;
        // Switched-off first, then most failures: what matters most stays
        // above the row cap.
        const rows = [...found].sort(
          (a, b) =>
            Number(b.switchedOff) - Number(a.switchedOff) || b.count - a.count,
        );
        const offCount = rows.filter((r) => r.switchedOff).length;
        cards.push({
          channel,
          ...CHANNELS[channel],
          count: rows.length,
          offCount,
          retryingCount: rows.length - offCount,
          worst: rows.reduce((w, r) => (r.count > w.count ? r : w), rows[0]),
          rows,
        });
      }
      return cards;
    },
  },
});
</script>

