<template>
  <div
    class="settings-sidebar"
    :class="{ 'settings-sidebar--collapsed': collapsed }"
    data-test="settings-sidebar"
  >
    <div class="sidebar-search">
      <f-input
        v-if="!collapsed"
        v-model="searchQuery"
        :placeholder="$t('search_settings') || 'Search settings...'"
        class="search-input"
        prepend-inner-icon="search"
        clearable
        data-test="settings-search-input"
        @clear="searchQuery = ''"
        @keydown.enter.prevent="openFirstHit"
      >
        <template #append>
          <button
            v-if="assistantAvailable"
            type="button"
            class="assistant-toggle"
            :class="{ 'assistant-toggle--active': assistantOpen }"
            :aria-pressed="assistantOpen"
            :aria-label="$t(assistantOpen ? 'settings_assistant_hide' : 'settings_assistant_show')"
            aria-controls="settings-assistant-panel"
            data-test="settings-assistant-toggle"
            @click.stop="$emit('update:assistant-open', !assistantOpen)"
          >
            <Icon icon="docbits:genie-lamp" width="18" height="18" class="block" />
          </button>
        </template>
      </f-input>
      <button
        v-else-if="assistantAvailable"
        type="button"
        class="assistant-toggle"
        :class="{ 'assistant-toggle--active': assistantOpen }"
        :aria-pressed="assistantOpen"
        :aria-label="$t(assistantOpen ? 'settings_assistant_hide' : 'settings_assistant_show')"
        aria-controls="settings-assistant-panel"
        data-test="settings-assistant-toggle"
        @click="$emit('update:assistant-open', !assistantOpen)"
      >
        <Icon icon="docbits:genie-lamp" width="18" height="18" class="block" />
      </button>
      <q-btn
        flat
        dense
        round
        size="sm"
        :icon="collapsed ? 'chevron_right' : 'chevron_left'"
        class="collapse-toggle"
        data-test="sidebar-collapse-toggle"
        @click="$emit('update:collapsed', !collapsed)"
      >
        <q-tooltip
          anchor="center right"
          self="center left"
          :offset="[10, 0]"
        >
          {{ collapsed ? ($t('expand_sidebar') || 'Expand sidebar') : ($t('collapse_sidebar') || 'Collapse sidebar') }}
        </q-tooltip>
      </q-btn>
    </div>

    <!-- Navigation -->
    <div class="sidebar-nav">
      <section
        v-if="!collapsed && searchQuery && (settingHits.length || assistantAvailable)"
        class="setting-hits"
        data-test="settings-search-results"
        :aria-label="$t('settings_search_results_label')"
      >
        <div class="category-header category-header--static">
          <span>{{ $t('settings_search_results_label') }}</span>
        </div>
        <button
          v-for="hit in settingHits"
          :key="hit.entry.setting_key"
          type="button"
          class="setting-hit"
          data-test="settings-search-hit"
          @click="openSettingHit(hit)"
        >
          <span class="setting-hit__label">{{ hit.label }}</span>
          <span v-if="hit.breadcrumb.length" class="setting-hit__path">{{
            hit.breadcrumb.join(' / ')
          }}</span>
        </button>
        <button
          v-if="assistantAvailable"
          type="button"
          class="setting-hit setting-hit--ask"
          data-test="settings-search-ask-assistant"
          @click="askAssistant"
        >
          <Icon icon="docbits:genie-lamp" width="16" height="16" class="shrink-0" />
          <span class="setting-hit__label">{{
            $t('settings_search_ask_assistant', { query: searchQuery.trim() })
          }}</span>
        </button>
      </section>
      <template v-for="category in filteredCategories" :key="category.id">
        <div
          class="category-header"
          :class="{ 'category-header--active': isCategoryActive(category.id) }"
          @click="navigateToCategory(category.id)"
        >
          <span>{{ category.title }}</span>
          <q-icon name="chevron_right" size="14px" class="category-chevron" />
        </div>

        <template v-for="item in category.items" :key="item.name">
          <!-- Parent item -->
          <div
            role="link"
            tabindex="0"
            class="nav-item"
            :class="{
              'nav-item--active': isActive(item),
              'nav-item--has-children': item.children && item.children.length > 0,
            }"
            :aria-current="isActive(item) ? 'page' : undefined"
            :data-test="`sidebar-item-${item.name}`"
            @click="onItemClick(item)"
            @keydown.enter="onItemClick(item)"
          >
            <Icon
              v-if="item.icon && item.icon.startsWith('mdi:')"
              :icon="item.icon"
              width="18"
              height="18"
              class="nav-item-icon"
            />
            <img
              v-else-if="item.icon"
              :src="'/' + item.icon"
              class="nav-item-icon"
              alt=""
            />
            <span class="nav-item-label">{{ $t(item.translate) }}</span>

            <!-- Expand chevron for items with children -->
            <q-icon
              v-if="item.children && item.children.length > 0"
              name="chevron_right"
              size="16px"
              class="nav-item-expand"
              :class="{ 'nav-item-expand--open': isExpanded(item) }"
              @click.stop="toggleExpand(item.name)"
            />

            <!-- Tooltip with description on hover -->
            <q-tooltip
              anchor="center right"
              self="center left"
              :offset="[10, 0]"
              class="nav-tooltip"
            >
              {{ $t(item.tooltip) }}
            </q-tooltip>
          </div>

          <!-- Children items (collapsible, hidden when collapsed) -->
          <template v-if="!collapsed && item.children && item.children.length > 0 && isExpanded(item)">
            <div
              v-for="child in getVisibleChildren(item)"
              :key="child.name"
              role="link"
              tabindex="0"
              class="nav-item nav-item--child"
              :class="{ 'nav-item--active': isActive(child) }"
              :aria-current="isActive(child) ? 'page' : undefined"
              :data-test="`sidebar-item-${child.name}`"
              @click="navigateTo(child)"
              @keydown.enter="navigateTo(child)"
            >
              <Icon
                v-if="child.icon && child.icon.startsWith('mdi:')"
                :icon="child.icon"
                width="16"
                height="16"
                class="nav-item-icon"
              />
              <img
                v-else-if="child.icon"
                :src="'/' + child.icon"
                class="nav-item-icon nav-item-icon--child"
                alt=""
              />
              <span class="nav-item-label">{{ $t(child.translate) }}</span>

              <q-tooltip
                anchor="center right"
                self="center left"
                :offset="[10, 0]"
                class="nav-tooltip"
              >
                {{ $t(child.tooltip) }}
              </q-tooltip>
            </div>
          </template>
        </template>
      </template>

      <!-- No results -->
      <div
        v-if="!collapsed && filteredCategories.length === 0 && !settingHits.length && searchQuery"
        class="no-results"
      >
        <q-icon name="search_off" size="32px" color="grey-5" />
        <p>{{ $t('no_results') || 'No settings found' }}</p>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import type { PropType } from 'vue';
import { Icon } from '@iconify/vue';

import type { CategoryData, SettingItem } from 'src/@types/settings';
import { jumpToAnchor } from 'src/utils/settingsAssistant/anchorHighlight';
import {
  buildSettingsIndex,
  resolveSettingPath,
  searchSettings,
} from 'src/utils/settingsAssistant/settingsSearchIndex';
import type {
  IndexedSetting,
  SettingSearchHit,
} from 'src/utils/settingsAssistant/settingsSearchIndex';

export default defineComponent({
  name: 'SettingsSidebar',

  components: { Icon },

  props: {
    categories: {
      type: Array as PropType<CategoryData[]>,
      required: true,
    },
    activeRoute: {
      type: String,
      default: '',
    },
    collapsed: {
      type: Boolean,
      default: false,
    },
    /** CORE-6108: org feature flag (SETTINGS_ASSISTANT_ENABLED) — hides the toggle entirely when off. */
    assistantAvailable: {
      type: Boolean,
      default: false,
    },
    /** CORE-6108: whether the settings-assistant chat panel is currently shown. */
    assistantOpen: {
      type: Boolean,
      default: false,
    },
  },

  emits: ['item-click', 'update:collapsed', 'update:assistant-open', 'ask-assistant'],

  data() {
    return {
      searchQuery: '',
      expandedItems: {} as Record<string, boolean>,
    };
  },

  computed: {
    settingsIndex(): IndexedSetting[] {
      return buildSettingsIndex((key) => String(this.$t(key)));
    },

    settingHits(): SettingSearchHit[] {
      return searchSettings(this.settingsIndex, this.searchQuery || '');
    },

    filteredCategories(): CategoryData[] {
      if (!this.searchQuery) return this.categories;

      const q = this.searchQuery.toLowerCase();
      return this.categories
        .map((cat) => ({
          ...cat,
          items: cat.items.filter((item) => {
            const parentMatch = this.itemMatchesSearch(item, q);
            const childMatch = item.children?.some((child) =>
              this.itemMatchesSearch(child, q),
            );
            return parentMatch || childMatch;
          }),
        }))
        .filter((cat) => cat.items.length > 0);
    },
  },

  watch: {
    activeRoute: {
      immediate: true,
      handler() {
        this.autoExpandActiveParent();
      },
    },
    categories: {
      immediate: true,
      handler() {
        this.autoExpandActiveParent();
      },
    },
  },

  methods: {
    itemMatchesSearch(item: SettingItem, q: string): boolean {
      return (
        this.$t(item.translate).toLowerCase().includes(q) ||
        this.$t(item.tooltip).toLowerCase().includes(q) ||
        item.name.toLowerCase().includes(q) ||
        (item.searchKeywords || []).some((kw) => kw.toLowerCase().includes(q))
      );
    },

    isActive(item: SettingItem): boolean {
      if (!item.route) return false;
      return this.activeRoute === item.route ||
             this.activeRoute.startsWith(item.route + '/') ||
             this.activeRoute.startsWith(item.route + '?');
    },

    isCategoryActive(categoryId: string): boolean {
      return this.activeRoute === `/settings/category/${categoryId}`;
    },

    isExpanded(item: SettingItem): boolean {
      // Always expand when searching
      if (this.searchQuery) return true;
      // Expand if a child is active
      if (item.children?.some((child) => this.isActive(child))) return true;
      // Otherwise use manual toggle state
      return !!this.expandedItems[item.name];
    },

    toggleExpand(itemName: string) {
      this.expandedItems[itemName] = !this.expandedItems[itemName];
    },

    getVisibleChildren(item: SettingItem): SettingItem[] {
      if (!item.children) return [];
      if (!this.searchQuery) return item.children;
      const q = this.searchQuery.toLowerCase();
      // If parent matches, show all children; otherwise only matching children
      if (this.itemMatchesSearch(item, q)) return item.children;
      return item.children.filter((child) => this.itemMatchesSearch(child, q));
    },

    autoExpandActiveParent() {
      if (!this.activeRoute) return;
      for (const cat of this.categories) {
        for (const item of cat.items) {
          if (item.children?.some((child) => this.isActive(child))) {
            this.expandedItems[item.name] = true;
          }
        }
      }
    },

    onItemClick(item: SettingItem) {
      if (item.children && item.children.length > 0) {
        this.toggleExpand(item.name);
      }
      if (item.route) {
        this.navigateTo(item);
      }
    },

    async openSettingHit(hit: SettingSearchHit) {
      const docType = this.$route?.params?.doc_type;
      const { path, exact } = resolveSettingPath(
        hit.entry,
        typeof docType === 'string' ? docType : undefined,
      );
      this.$emit('item-click', hit.entry);
      await this.$router.push(path);
      if (exact) await jumpToAnchor(hit.entry.anchor);
    },

    openFirstHit() {
      const [first] = this.settingHits;
      if (first) this.openSettingHit(first);
      else if (this.assistantAvailable && this.searchQuery?.trim()) this.askAssistant();
    },

    askAssistant() {
      const question = this.searchQuery?.trim();
      if (!question) return;
      this.$emit('ask-assistant', question);
    },

    navigateToCategory(categoryId: string) {
      this.$router.push(`/settings/category/${categoryId}`);
    },

    navigateTo(item: SettingItem) {
      if (item.route) {
        this.$router.push(item.route);
        this.$emit('item-click', item);
      }
    },
  },
});
</script>

