/**
 * CORE-6145 — client for switching off / deleting a broken email-import
 * mailbox or FTP/SFTP connection from the Settings Assistant (health notice
 * and chat cards)
 * (doc2-api `POST /v3/settings-assistant/import-email/{preview,confirm,undo}`).
 *
 * Same three steps as the Wave 1 apply flow: `preview` writes nothing,
 * `confirm` only ever runs from the user's own click on the confirm button,
 * `undo` restores the previous state within 15 minutes. Both actions are
 * reversible on the server (an `is_active` flip / a soft delete).
 *
 * Errors are the apply flow's `ApplyRequestError` (status + errorCode), so a
 * 409 (the mailbox changed since the preview) can be told apart from the rest.
 */
// Direct file imports, NOT the src/generated-api-sdk barrel (CLAUDE.md's
// barrel-import rule).
import { SettingsAssistantImportEmailService as GeneratedImportEmailService } from 'src/generated-api-sdk/services/SettingsAssistantImportEmailService';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import { toApplyRequestError } from 'src/services/settingsAssistant/settingsAssistantApplyService';

export type ImportEmailAction = 'deactivate' | 'delete';
export type ImportChannel = 'email' | 'ftp';

export interface ImportEmailActionPreview {
  preview_id: string;
  channel?: ImportChannel;
  action: ImportEmailAction;
  /** Credentials are never part of this; `email` is null for a mailbox
   * that was saved without an address, and absent for an FTP connection
   * (whose `server` is its host only). */
  config: {
    id: number | string;
    email?: string | null;
    server: string | null;
    ftp_type?: string | null;
    is_active: boolean;
    auth_failed_count: number;
  };
  reversible: boolean;
  expires_in_seconds: number;
}

export interface ImportEmailActionConfirmResult {
  success: boolean;
  channel?: ImportChannel;
  action: ImportEmailAction;
  config_id: number | string;
  /** null: the change cannot be undone (a delete). */
  undo_id: string | null;
  undo_expires_in_seconds: number;
}

export interface ImportEmailActionUndoResult {
  success: boolean;
  channel?: ImportChannel;
  action: ImportEmailAction;
  config_id: number | string;
}

export const settingsAssistantImportEmailService = {
  /** Dry-run only — writes nothing. */
  async preview(
    configId: number | string,
    action: ImportEmailAction,
    channel: ImportChannel = 'email',
  ): Promise<ImportEmailActionPreview> {
    try {
      return (await GeneratedImportEmailService.importEmailActionPreviewV3SettingsAssistantImportEmailPreviewPost(
        {
          requestBody: { config_id: configId, action, channel },
          xOrgId: getOrgId(),
        },
      )) as ImportEmailActionPreview;
    } catch (error) {
      throw toApplyRequestError(error);
    }
  },

  /** Changes the mailbox. Only ever call this as the direct result of the
   * user's own click on the confirm button. */
  async confirm(previewId: string): Promise<ImportEmailActionConfirmResult> {
    try {
      return (await GeneratedImportEmailService.importEmailActionConfirmV3SettingsAssistantImportEmailConfirmPost(
        {
          requestBody: { preview_id: previewId },
          xOrgId: getOrgId(),
        },
      )) as ImportEmailActionConfirmResult;
    } catch (error) {
      throw toApplyRequestError(error);
    }
  },

  /** Restores the state a confirmed change replaced. */
  async undo(undoId: string): Promise<ImportEmailActionUndoResult> {
    try {
      return (await GeneratedImportEmailService.importEmailActionUndoV3SettingsAssistantImportEmailUndoPost(
        {
          requestBody: { undo_id: undoId },
          xOrgId: getOrgId(),
        },
      )) as ImportEmailActionUndoResult;
    } catch (error) {
      throw toApplyRequestError(error);
    }
  },
};

export default settingsAssistantImportEmailService;
