/**
 * CORE-6108 — page-aware greeting for the settings assistant.
 *
 * `settingsPageQuestions.json` is the ONE route → questions map: every
 * `/settings` page of the router (hub and category overviews excluded — they
 * keep the generic greeting) with the Tolgee key of its title (the sidebar
 * label where the page has one) and three Tolgee keys of example questions
 * about that page. A unit spec asserts every settings route in
 * `src/router/routes.ts` has an entry, so a new page cannot be forgotten.
 *
 * The API (doc2-api `helpers/settings_assistant/settings_pages.py`) mirrors
 * the same route list: it validates the `page` the chat sends and answers a
 * clicked question with at least a navigation card for that page.
 */
import pageQuestions from 'src/components/SettingsAssistant/settingsPageQuestions.json';

export interface SettingsPageQuestions {
  /** vue-router path pattern, e.g. `/settings/fields/:type/:sub_doc_type?`. */
  route: string;
  /** Tolgee key of the page title. */
  titleKey: string;
  /** Tolgee keys of the example questions shown as chips. */
  questionKeys: string[];
  /**
   * CORE-6103 — optional page-specific offer that replaces the generic
   * "Soll ich dir mit den Einstellungen hier helfen?" line. Translated with
   * the page's route params (e.g. `{doc_type}`).
   */
  greetingKey?: string;
  /**
   * CORE-6103 — when set, the FIRST question is the page's primary action:
   * rendered as the highlighted chip and sent with this `intent` in the
   * chat request (doc2-api `ChatRequest.intent`), a deterministic signal
   * the server honours only on the matching page.
   */
  primaryIntent?: 'create_transformation_rule';
}

export const SETTINGS_PAGE_QUESTIONS: SettingsPageQuestions[] =
  pageQuestions.pages as SettingsPageQuestions[];

/** Same segment rule as the API: unreserved characters or a %XX escape. */
const SEGMENT = '(?:[A-Za-z0-9_\\-~]|%[0-9A-Fa-f]{2})(?:[A-Za-z0-9_\\-~.]|%[0-9A-Fa-f]{2})*';

function routeRegex(route: string): RegExp {
  const parts = route
    .replace(/^\/+|\/+$/g, '')
    .split('/')
    .map((segment) => {
      if (!segment.startsWith(':')) {
        return '/' + segment.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      }
      return segment.endsWith('?') ? `(?:/${SEGMENT})?` : `/${SEGMENT}`;
    });
  return new RegExp(`^${parts.join('')}$`);
}

function specificity(route: string): [number, number] {
  const segments = route.replace(/^\/+|\/+$/g, '').split('/');
  return [segments.filter((s) => !s.startsWith(':')).length, segments.length];
}

/** Most specific pattern first — `/settings/doc-type-settings/pdf-layout`
 * wins over `/settings/doc-type-settings/:doc_type/:ai_prompt?`. */
const COMPILED = SETTINGS_PAGE_QUESTIONS.map((entry) => ({
  entry,
  regex: routeRegex(entry.route),
  rank: specificity(entry.route),
})).sort((a, b) => b.rank[0] - a.rank[0] || b.rank[1] - a.rank[1]);

/**
 * The settings page for a concrete path (`$route.path`), or null for the
 * hub, a category overview, or anything unknown — those keep the generic
 * greeting. Query/hash and one trailing slash are ignored.
 */
export function resolveSettingsPage(
  path: string | null | undefined,
): SettingsPageQuestions | null {
  if (!path) return null;
  let clean = path.split(/[?#]/)[0];
  if (clean.length > 1 && clean.endsWith('/')) clean = clean.slice(0, -1);
  if (!clean.startsWith('/settings/') || clean.includes('..')) return null;
  const hit = COMPILED.find(({ regex }) => regex.test(clean));
  return hit ? hit.entry : null;
}

/**
 * CORE-6103 — the concrete values of a page pattern's `:params` in `path`
 * (e.g. `{ doc_type: 'INVOICE' }` for `/settings/transformation-rules/:doc_type`
 * and `/settings/transformation-rules/INVOICE`), URI-decoded. Missing optional
 * params are omitted; a path that does not match yields `{}`.
 */
export function settingsPageParams(
  route: string,
  path: string | null | undefined,
): Record<string, string> {
  if (!path) return {};
  let clean = path.split(/[?#]/)[0];
  if (clean.length > 1 && clean.endsWith('/')) clean = clean.slice(0, -1);
  if (!routeRegex(route).test(clean)) return {};
  const patternSegments = route.replace(/^\/+|\/+$/g, '').split('/');
  const pathSegments = clean.replace(/^\/+|\/+$/g, '').split('/');
  const params: Record<string, string> = {};
  patternSegments.forEach((segment, idx) => {
    if (!segment.startsWith(':') || pathSegments[idx] === undefined) return;
    const name = segment.slice(1).replace(/\?$/, '');
    try {
      params[name] = decodeURIComponent(pathSegments[idx]);
    } catch {
      params[name] = pathSegments[idx];
    }
  });
  return params;
}
