export const DEFAULT_SIDEBAR_WIDTH = 260;
export const MIN_SIDEBAR_WIDTH = 220;
export const MAX_SIDEBAR_WIDTH = 480;
export const SIDEBAR_RESIZE_KEYBOARD_STEP = 16;
export const SIDEBAR_WIDTH_STORAGE_KEY = 'docbits_settings_sidebar_width_v1';

export function clampSidebarWidth(px: number): number {
  if (!Number.isFinite(px)) return DEFAULT_SIDEBAR_WIDTH;
  return Math.min(Math.max(Math.round(px), MIN_SIDEBAR_WIDTH), MAX_SIDEBAR_WIDTH);
}

export function readSidebarWidth(): number {
  try {
    const raw = window.localStorage.getItem(SIDEBAR_WIDTH_STORAGE_KEY);
    return raw ? clampSidebarWidth(Number(raw)) : DEFAULT_SIDEBAR_WIDTH;
  } catch {
    return DEFAULT_SIDEBAR_WIDTH;
  }
}

export function persistSidebarWidth(px: number): void {
  try {
    window.localStorage.setItem(SIDEBAR_WIDTH_STORAGE_KEY, String(clampSidebarWidth(px)));
  } catch {
    // storage blocked (private window); the width just isn't remembered
  }
}
