<template>
  <q-dialog
    v-model="visible"
    persistent
    data-test="settings-assistant-apply-dialog"
  >
    <q-card class="settings-assistant-apply">
      <q-toolbar class="text-white secondary-toolbar">
        <q-toolbar-title>{{
          $t('settings_assistant_apply_dialog_title')
        }}</q-toolbar-title>
        <q-btn
          flat
          round
          dense
          icon="close"
          class="text-white"
          data-test="settings-assistant-apply-close"
          @click="onCancel"
        />
      </q-toolbar>

      <q-card-section
        v-if="phase === 'loading'"
        class="flex items-center gap-2"
        data-test="settings-assistant-apply-loading"
      >
        <q-spinner size="20px" color="primary" />
        <span class="text-sm text-muted-foreground">{{
          $t('settings_assistant_apply_loading')
        }}</span>
      </q-card-section>

      <q-card-section
        v-else-if="phase === 'preview' && preview"
        data-test="settings-assistant-apply-preview"
      >
        <p class="font-semibold">{{ settingLabel }}</p>
        <p class="text-sm text-muted-foreground">{{ scopeLabel }}</p>
        <div class="settings-assistant-apply__values mt-3">
          <span
            class="settings-assistant-apply__value settings-assistant-apply__value--old"
            data-test="settings-assistant-apply-current-value"
            >{{ formatValue(preview.current_value, preview.value_type, preview.setting_key) }}</span
          >
          <Icon
            icon="mdi:arrow-right"
            width="18"
            height="18"
            class="text-muted-foreground"
          />
          <span
            class="settings-assistant-apply__value settings-assistant-apply__value--new"
            data-test="settings-assistant-apply-proposed-value"
            >{{ formatValue(preview.proposed_value, preview.value_type, preview.setting_key) }}</span
          >
        </div>
      </q-card-section>

      <q-card-section
        v-else-if="phase === 'stale'"
        class="flex items-start gap-2 text-sm"
        data-test="settings-assistant-apply-stale"
      >
        <Icon
          icon="mdi:alert-outline"
          width="20"
          height="20"
          class="text-warning shrink-0 mt-0.5"
        />
        <span>{{ $t('settings_assistant_apply_stale') }}</span>
      </q-card-section>

      <q-card-section
        v-else-if="phase === 'conflict'"
        class="flex items-start gap-2 text-sm"
        data-test="settings-assistant-apply-conflict"
      >
        <Icon
          icon="mdi:help-circle-outline"
          width="20"
          height="20"
          class="text-warning shrink-0 mt-0.5"
        />
        <span>{{ $t('settings_assistant_apply_conflict') }}</span>
      </q-card-section>

      <q-card-section
        v-else-if="phase === 'error'"
        class="flex flex-col gap-2 text-sm"
        data-test="settings-assistant-apply-error"
      >
        <!-- CORE-6108 review: the label used to disappear once the error
             phase replaced the preview section entirely — shown here
             whenever a preview was already fetched (confirm/undo failures),
             absent only for a preview-fetch failure itself (no label known
             yet at that point). -->
        <p v-if="settingLabel" class="font-semibold text-foreground">
          {{ settingLabel }}
        </p>
        <div class="flex items-start gap-2 text-destructive">
          <Icon
            icon="mdi:alert-circle-outline"
            width="20"
            height="20"
            class="shrink-0 mt-0.5"
          />
          <span>{{ errorMessage }}</span>
        </div>
        <button
          v-if="errorTraceId"
          type="button"
          class="settings-assistant-apply__trace"
          data-test="settings-assistant-apply-trace-id"
          :title="$t('login_error_trace_id_copy')"
          @click="copyTraceId"
        >
          {{ copiedTrace ? $t('settings_assistant_trace_copied') : $t('login_error_trace_id') }}<template v-if="!copiedTrace">: <span class="font-mono">{{ errorTraceId }}</span></template>
        </button>
      </q-card-section>

      <q-card-actions align="right" class="gap-1">
        <q-btn
          flat
          no-caps
          color="grey-7"
          :label="$t('cancel')"
          data-test="settings-assistant-apply-cancel"
          @click="onCancel"
        />
        <q-btn
          v-if="phase === 'stale' || phase === 'conflict'"
          unelevated
          no-caps
          color="primary"
          :label="$t('settings_assistant_retry')"
          data-test="settings-assistant-apply-retry"
          @click="startPreview"
        />
        <q-btn
          v-else
          unelevated
          no-caps
          color="primary"
          :loading="confirming"
          :disable="phase !== 'preview' || confirming"
          :label="$t('confirm')"
          data-test="settings-assistant-apply-confirm"
          @click="onConfirm"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import { storeToRefs } from 'pinia';
import { Icon } from '@iconify/vue';
import { useSettingStore } from 'src/store/main';
import { notify } from 'src/components/notifications/notify';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import settingsAssistantApplyService, {
  ApplyRequestError,
  type ApplyPreviewResult,
} from 'src/services/settingsAssistant/settingsAssistantApplyService';
import { updateSettingStoreValue } from 'src/utils/settingsAssistant/updateSettingStoreValue';
import { formatRecommendationValue } from 'src/utils/settingsAssistant/formatRecommendationValue';

/** The minimum a recommendation card needs to carry for "Übernehmen" to be
 * offered — see CORE-6109's contract in the doc2-api PR body. */
export interface ApplyDialogRecommendation {
  setting_key: string;
  proposed_value: boolean | string;
}

// Codex review (2026-09-28): 'conflict' is distinct from 'stale' — stale
// means confirm was REFUSED (409, nothing written); conflict means the
// backend reports applied but NOT verified (the write happened but the
// immediate read-back disagreed) — a rarer, more concerning case that must
// not be shown as a plain success.
type Phase = 'loading' | 'preview' | 'stale' | 'conflict' | 'error';

export default defineComponent({
  name: 'SettingsAssistantApplyDialog',

  components: { Icon },

  props: {
    modelValue: {
      type: Boolean,
      default: false,
    },
    recommendation: {
      type: Object as PropType<ApplyDialogRecommendation | null>,
      default: null,
    },
  },

  emits: ['update:modelValue', 'applied', 'undone'],

  data() {
    return {
      phase: 'loading' as Phase,
      preview: null as ApplyPreviewResult | null,
      errorMessage: '',
      errorTraceId: '',
      copiedTrace: false,
      confirming: false,
      undoing: false,
    };
  },

  computed: {
    visible: {
      get(): boolean {
        return this.modelValue;
      },
      set(value: boolean) {
        this.$emit('update:modelValue', value);
      },
    },

    settingLabel(): string {
      // label_key is a Tolgee key by contract (helpers/settings_assistant/
      // deep_links.py: "Tolgee key for the setting's own label") — used
      // as-is, with the key itself as the fallback vue-i18n already gives
      // for a missing translation.
      if (!this.preview) return '';
      return this.$t(this.preview.label_key);
    },

    scopeLabel(): string {
      if (!this.preview) return '';
      // Wave 1 is org-scoped only (deep_links.py's writable entries are all
      // scope: "org") — the generic "organization" key covers it; a future
      // doc_type/sub_org scope would need its own key when it lands.
      return this.preview.scope === 'org'
        ? this.$t('organization')
        : this.preview.scope;
    },
  },

  watch: {
    modelValue: {
      // immediate: true so a dialog created already-open (e.g. driven by a
      // parent that mounts it with modelValue already true) still previews
      // — not just one that transitions false -> true after mount.
      immediate: true,
      handler(open: boolean) {
        if (open) this.startPreview();
      },
    },
  },

  setup() {
    const settingStore = useSettingStore();
    const { user_settings, org_based_settings, user_based_settings } =
      storeToRefs(settingStore);
    return { user_settings, org_based_settings, user_based_settings };
  },

  methods: {
    /**
     * Codex review (2026-09-29): delegates to the shared
     * formatRecommendationValue (src/utils/settingsAssistant/
     * formatRecommendationValue.ts) — this used to have its own, narrower
     * copy (boolean/null only, everything else `String(value)`), which hit
     * the exact same "[object Object]" bug the recommendation card's
     * formatRecValue had for an object-valued setting. Sharing one
     * implementation means a future fix only has to happen once.
     */
    formatValue(
      value: unknown,
      valueType?: string,
      settingKey?: string,
    ): string {
      return formatRecommendationValue(value, this.$t, valueType, settingKey);
    },

    /**
     * CORE-6108 review: the well-known status codes get a short translated
     * message rather than surfacing whatever raw text the backend sent
     * (that text is still readable now — messageFromErrorBody fixed the
     * "[object Object]" bug — but "translated over raw" is the safer
     * default for anything shown to an end user).
     */
    errorMessageFor(err: unknown): string {
      if (err instanceof ApplyRequestError) {
        if (err.status === 429) {
          return String(this.$t('settings_assistant_rate_limited'));
        }
        if (err.status === 403) {
          return String(this.$t('settings_assistant_forbidden'));
        }
        if (err.status === 503) {
          return String(this.$t('settings_assistant_unavailable_retry'));
        }
        if (err.message) return err.message;
      } else if (err instanceof Error && err.message) {
        return err.message;
      }
      return String(this.$t('settings_assistant_error'));
    },

    errorTraceIdFor(err: unknown): string {
      return err instanceof ApplyRequestError ? err.traceId : '';
    },

    async copyTraceId() {
      try {
        await navigator.clipboard.writeText(this.errorTraceId);
        this.copiedTrace = true;
        setTimeout(() => {
          this.copiedTrace = false;
        }, 2000);
      } catch {
        // clipboard refused — nothing else to do
      }
    },

    async startPreview() {
      if (!this.recommendation) return;
      this.phase = 'loading';
      this.errorMessage = '';
      this.errorTraceId = '';
      this.preview = null;
      try {
        this.preview = await settingsAssistantApplyService.preview(
          this.recommendation.setting_key,
          this.recommendation.proposed_value,
        );
        this.phase = 'preview';
      } catch (err) {
        this.errorMessage = this.errorMessageFor(err);
        this.errorTraceId = this.errorTraceIdFor(err);
        this.phase = 'error';
      }
    },

    updateStoreValue(settingKey: string, value: unknown) {
      // Mirrors useSettingStore().updateSetting() AFTER its own API call —
      // the confirm/undo endpoints already wrote the value server-side, so
      // this is a store refresh, not a second write. Shared with
      // SettingsLayout.vue's undoAppliedChange (CORE-6108 review) so the
      // two write paths can't drift again.
      updateSettingStoreValue(
        {
          user_settings: this.user_settings,
          org_based_settings: this.org_based_settings,
          user_based_settings: this.user_based_settings,
        },
        settingKey,
        value,
      );
    },

    async onConfirm() {
      if (!this.preview) return;
      // Codex review: a synchronous in-flight guard — :disable on the
      // button already prevents most double-clicks, but that is reactive
      // UI state, not a guarantee against a second call slipping in before
      // the DOM updates (e.g. a fast double-tap, or a programmatic retry).
      if (this.confirming) return;
      this.confirming = true;
      // Captured BEFORE sending, not read again after the response — the
      // admin may switch org context while the request is in flight (a
      // multi-org admin, a slow network). The undo_id gets bound to THIS
      // value, and the response itself is only applied if the org is still
      // the same one by the time it arrives.
      const orgAtRequest = getOrgId();
      try {
        const result = await settingsAssistantApplyService.confirm(
          this.preview.preview_id,
        );
        if (getOrgId() !== orgAtRequest) {
          // The org changed while this request was in flight — the write
          // did happen (server-side, in orgAtRequest), but applying its
          // result to whatever is now showing would attribute someone
          // else's org's change to the current view.
          notify.info(this.$t('settings_assistant_apply_org_changed'));
          this.visible = false;
          return;
        }
        if (!result.applied || !result.verified) {
          // The write may or may not actually be in effect — showing a
          // plain success here would be a lie either way. Shown as its own
          // phase (not auto-retried): the admin reads the conflict message
          // and explicitly asks to re-check, which re-previews to fetch
          // the authoritative current value instead of trusting the
          // response's own (unverified) new_value.
          this.phase = 'conflict';
          return;
        }
        this.updateStoreValue(result.setting_key, result.new_value);
        this.visible = false;
        notify.success(this.$t('settings_assistant_apply_success'), {
          action: {
            label: this.$t('undo'),
            onClick: () => this.onUndo(result.undo_id, orgAtRequest),
          },
        });
        // CORE-6108: enrich the emitted payload with what the conversation
        // transcript needs (label + formatted values) — result itself
        // (ApplyConfirmResult) carries no label, only setting_key.
        this.$emit('applied', {
          ...result,
          label_key: this.preview.label_key,
          // result (ApplyConfirmResult) carries no value_type of its own —
          // it's the same setting as the preview this confirm followed, so
          // that preview's value_type still applies.
          formattedOldValue: this.formatValue(
            result.old_value,
            this.preview.value_type,
            result.setting_key,
          ),
          formattedNewValue: this.formatValue(
            result.new_value,
            this.preview.value_type,
            result.setting_key,
          ),
        });
      } catch (err) {
        if (err instanceof ApplyRequestError && err.status === 409) {
          this.phase = 'stale';
        } else {
          this.errorMessage = this.errorMessageFor(err);
          this.errorTraceId = this.errorTraceIdFor(err);
          this.phase = 'error';
        }
      } finally {
        this.confirming = false;
      }
    },

    async onUndo(undoId: string, orgAtConfirm: string) {
      if (this.undoing) return;
      if (getOrgId() !== orgAtConfirm) {
        notify.info(this.$t('settings_assistant_apply_undo_wrong_org'));
        return;
      }
      this.undoing = true;
      try {
        const result = await settingsAssistantApplyService.undo(undoId);
        if (getOrgId() !== orgAtConfirm) {
          // Switched again WHILE the undo request was in flight.
          notify.info(this.$t('settings_assistant_apply_org_changed'));
          return;
        }
        if (!result.applied || !result.verified) {
          notify.error(
            this.$t('settings_assistant_apply_error_undo'),
            this.$t('settings_assistant_apply_stale'),
          );
          return;
        }
        this.updateStoreValue(result.setting_key, result.restored_value);
        notify.success(this.$t('settings_assistant_apply_undo_success'));
        this.$emit('undone', { ...result, undo_id: undoId });
      } catch (err) {
        notify.error(
          this.$t('settings_assistant_apply_error_undo'),
          this.errorMessageFor(err),
        );
      } finally {
        this.undoing = false;
      }
    },

    onCancel() {
      this.visible = false;
    },
  },
});
</script>

<style lang="scss" scoped>
.settings-assistant-apply {
  width: 100%;
  max-width: 420px;
}

.settings-assistant-apply__values {
  display: flex;
  align-items: center;
  gap: 10px;
}

.settings-assistant-apply__value {
  padding: 4px 10px;
  border-radius: 6px;
  font-size: 13px;
  font-weight: 600;
  border: 1px solid var(--border);

  &--old {
    color: var(--muted-foreground);
    background: var(--muted);
  }

  &--new {
    color: var(--primary-foreground);
    background: var(--primary);
    border-color: var(--primary);
  }
}

.settings-assistant-apply__trace {
  align-self: flex-start;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--muted-foreground);
