<template>
  <AssistantActionCard
    :kicker="kicker"
    :title="title"
    :badge="badge"
    :reason="reason"
    :meta="meta"
    :variant="offer.switched_off ? 'danger' : 'warning'"
    test-id="settings-assistant-import-action"
    data-test="settings-assistant-import-connection"
    :data-channel="offer.channel"
  >
    <template #actions>
      <!-- A change was made: say so, offer undo. -->
      <div
        v-if="done"
        class="sa-import-card__done"
        role="status"
        data-test="settings-assistant-import-done"
      >
        <span data-test="settings-assistant-import-done-text">{{
          doneText
        }}</span>
        <q-btn
          v-if="done.undoId"
          flat
          dense
          no-caps
          :disable="busy"
          :label="$t('settings_assistant_health_action_undo')"
          data-test="settings-assistant-import-undo"
          @click="undoAction"
        />
      </div>

      <!-- Step 2: the admin's own click on "Yes" is the only thing that writes. -->
      <div
        v-if="pending"
        class="sa-import-card__confirm"
        role="group"
        :aria-label="confirmText"
        data-test="settings-assistant-import-confirm"
      >
        <p class="text-sm" data-test="settings-assistant-import-confirm-text">
          {{ confirmText }}
        </p>
        <div class="sa-import-card__buttons">
          <q-btn
            unelevated
            no-caps
            :color="pending.action === 'delete' ? 'negative' : 'primary'"
            :disable="busy"
            :label="
              $t(
                pending.action === 'delete'
                  ? 'settings_assistant_health_action_confirm_delete_yes'
                  : 'settings_assistant_health_action_confirm_deactivate_yes',
              )
            "
            data-test="settings-assistant-import-confirm-yes"
            @click="confirmAction"
          />
          <q-btn
            flat
            no-caps
            :disable="busy"
            :label="$t('settings_assistant_health_action_cancel')"
            data-test="settings-assistant-import-confirm-cancel"
            @click="cancelAction"
          />
        </div>
      </div>

      <!-- Step 1: a dry run. Nothing changes until the admin says yes. -->
      <div
        v-else-if="canDeactivate || canDelete"
        class="sa-import-card__buttons"
      >
        <q-btn
          v-if="canDeactivate"
          unelevated
          no-caps
          color="primary"
          :disable="busy"
          :label="$t('settings_assistant_health_action_deactivate')"
          data-test="settings-assistant-import-deactivate"
          @click="startAction('deactivate')"
        />
        <q-btn
          v-if="canDelete"
          outline
          no-caps
          color="negative"
          :disable="busy"
          :label="$t('settings_assistant_health_action_delete')"
          data-test="settings-assistant-import-delete"
          @click="startAction('delete')"
        />
      </div>

      <p
        v-if="errorKey"
        class="sa-import-card__error text-sm"
        role="alert"
        data-test="settings-assistant-import-error"
      >
        {{ $t(errorKey) }}
      </p>
    </template>
  </AssistantActionCard>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import AssistantActionCard from 'src/components/AssistantChat/AssistantActionCard.vue';
import { ApplyRequestError } from 'src/services/settingsAssistant/settingsAssistantApplyService';
import {
  settingsAssistantImportEmailService,
  type ImportEmailAction,
} from 'src/services/settingsAssistant/settingsAssistantImportEmailService';
import {
  reasonKeyFor,
  switchedOffText,
  type ImportActionOffer,
} from 'src/utils/settingsAssistant/importActionOffers';
import pythonDateFormatToJs from 'src/utils/pythonDateFormatToJs';
import { useSettingStore } from 'src/store/main';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import { logger } from 'src/utils/logger';

/** The user preference with the date format (`date_pattern_setting` in
 * src/constants, which is not imported here: it loads the whole i18n boot). */
const DATE_PATTERN_SETTING = 'DATE_PATTERN';

interface Pending {
  action: ImportEmailAction;
  previewId: string;
  server: string;
}

interface Done {
  action: ImportEmailAction;
  /** null for a delete: nothing to undo. */
  undoId: string | null;
}

/**
 * CORE-6145 — one card per import connection that stopped working, under the
 * assistant's answer. The server decides WHICH connections appear; the model
 * has no tool that can change one. Switching off or deleting is the same three
 * steps as everywhere (preview -> the admin's own click on "Yes" -> confirm,
 * undo for 15 minutes), for a mailbox and for an FTP/SFTP connection alike.
 */
export default defineComponent({
  name: 'SettingsAssistantImportConnectionCard',

  components: { AssistantActionCard },

  props: {
    offer: { type: Object as PropType<ImportActionOffer>, required: true },
  },

  emits: ['changed'],

  data() {
    return {
      pending: null as Pending | null,
      done: null as Done | null,
      busy: false,
      errorKey: '',
    };
  },

  computed: {
    kicker(): string {
      return this.offer.channel === 'ftp'
        ? this.$t('ftp_import')
        : this.$t('settings_email_import');
    },
    /** The address / host; a mailbox saved without one gets a described name. */
    title(): string {
      return (
        this.offer.label ?? this.$t('settings_assistant_health_action_no_email')
      );
    },
    badge(): string {
      return this.$t(
        this.offer.switched_off
          ? 'settings_assistant_health_row_off'
          : 'settings_assistant_health_row_retrying',
      );
    },
    /** CORE-6319: "Deactivated on {date} by {name}" when both are recorded,
     * "Deactivated (details not available)" otherwise - never a guess. */
    switchedOffLine(): string {
      if (!this.offer.switched_off) return '';
      const { key, params } = switchedOffText(this.offer, this.datePattern);
      return this.$t(key, params);
    },
    /** The user's date preference as a Quasar format; null = DD.MM.YYYY. */
    datePattern(): string | null {
      try {
        const pref = useSettingStore().user_settings?.[DATE_PATTERN_SETTING];
        return pref
          ? String(
              pythonDateFormatToJs.methods.convertPYDateFormatToJS(
                String(pref),
              ),
            ) || null
          : null;
      } catch {
        return null; // no store (embedded/test): the default format
      }
    },
    reason(): string {
      // A plain switch-off has no recorded reason: say when and by whom.
      if (this.offer.reason_code === 'switched_off' && this.switchedOffLine) {
        return this.switchedOffLine;
      }
      return this.$t(reasonKeyFor(this.offer.reason_code));
    },
    meta(): string {
      const count = this.offer.failed_attempts;
      const failures = this.$t(
        count === 1
          ? 'settings_assistant_health_row_failures_one'
          : 'settings_assistant_health_row_failures_other',
        { count },
      );
      // A connection switched off for a failure keeps the failure as its
      // reason; the switch-off record goes next to the counter.
      return this.offer.switched_off &&
        this.offer.reason_code !== 'switched_off'
        ? `${failures} · ${this.switchedOffLine}`
        : failures;
    },
    /** What the card can still do now: a connection switched off here stays
     * off (delete is still possible), and a deleted one has nothing left. */
    canDeactivate(): boolean {
      return this.offer.can_deactivate && !this.done;
    },
    canDelete(): boolean {
      return this.offer.can_delete && this.done?.action !== 'delete';
    },
    confirmText(): string {
      const p = this.pending;
      if (!p) return '';
      return this.$t(
        p.action === 'delete'
          ? 'settings_assistant_health_action_confirm_delete'
          : 'settings_assistant_health_action_confirm_deactivate',
        { config: this.title, server: p.server },
      );
    },
    doneText(): string {
      const d = this.done;
      if (!d) return '';
      return this.$t(
        d.action === 'delete'
          ? 'settings_assistant_health_action_done_delete'
          : 'settings_assistant_health_action_done_deactivate',
        { config: this.title },
      );
    },
  },

  methods: {
    /** 409 = the connection changed since the preview; anything else is
     * generic. Only status / error class are logged (customer data). */
    failureKey(err: unknown): string {
      const status = (err as { status?: number })?.status;
      if (err instanceof ApplyRequestError && status === 409) {
        return 'settings_assistant_health_action_error_stale';
      }
      logger.error('[SettingsAssistantImportConnectionCard]', 'action failed', {
        status,
        errorClass: (err as Error)?.constructor?.name,
      });
      return 'settings_assistant_health_action_error';
    },

    async startAction(action: ImportEmailAction) {
      if (this.busy) return;
      this.busy = true;
      this.errorKey = '';
      this.pending = null;
      const orgId = getOrgId();
      try {
        const preview = await settingsAssistantImportEmailService.preview(
          this.offer.config_id,
          action,
          this.offer.channel,
        );
        if (orgId !== getOrgId()) return;
        this.pending = {
          action,
          previewId: preview.preview_id,
          server: preview.config?.server ?? '',
        };
      } catch (err) {
        if (orgId !== getOrgId()) return;
        this.errorKey = this.failureKey(err);
      } finally {
        this.busy = false;
      }
    },

    cancelAction() {
      this.pending = null;
    },

    async confirmAction() {
      const pending = this.pending;
      if (!pending || this.busy) return;
      this.busy = true;
      const orgId = getOrgId();
      try {
        const result = await settingsAssistantImportEmailService.confirm(
          pending.previewId,
        );
        if (orgId !== getOrgId()) return;
        this.pending = null;
        this.errorKey = '';
        this.done = { action: pending.action, undoId: result.undo_id };
        this.$emit('changed', {
          action: pending.action,
          channel: this.offer.channel,
        });
      } catch (err) {
        if (orgId !== getOrgId()) return;
        this.pending = null;
        this.errorKey = this.failureKey(err);
      } finally {
        this.busy = false;
      }
    },

    async undoAction() {
      const done = this.done;
      if (!done?.undoId || this.busy) return;
      this.busy = true;
      const orgId = getOrgId();
      try {
        await settingsAssistantImportEmailService.undo(done.undoId);
        if (orgId !== getOrgId()) return;
        this.done = null;
        this.$emit('changed', {
          action: 'undo',
          channel: this.offer.channel,
        });
      } catch (err) {
        if (orgId !== getOrgId()) return;
        // The undo no longer applies (expired or changed again): drop it.
        this.done = null;
        this.errorKey = this.failureKey(err);
      } finally {
        this.busy = false;
      }
    },
  },
});
</script>

<style lang="scss" scoped>
.sa-import-card__buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.sa-import-card__confirm {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.sa-import-card__done {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.sa-import-card__error {
  margin-top: 6px;
  color: var(--destructive-badge-text, var(--destructive));
}
</style>
