<template>
  <!--
    CORE-6103 — the transcript line after a rule was created from the chat:
    "Regel angelegt (inaktiv)", "Zur Regel" (its edit page) and, for the
    15-minute undo window, "Rückgängig" with a live countdown. Persistent in
    the conversation, not a toast that disappears after a few seconds.
  -->
  <div class="sa-rule-entry" data-test="settings-assistant-rule-created">
    <div class="sa-rule-entry__line">
      <Icon
        :icon="creation.undone ? 'mdi:undo-variant' : 'mdi:check-circle-outline'"
        width="16"
        height="16"
        class="shrink-0"
        :class="creation.undone ? 'text-muted-foreground' : 'text-success'"
      />
      <span class="sa-rule-entry__text">{{ content }}</span>
    </div>

    <p
      v-if="creation.undone"
      class="sa-rule-entry__status"
      data-test="settings-assistant-rule-undone"
    >
      {{ $t('settings_assistant_rule_undone') }}
    </p>

    <div v-else class="sa-rule-entry__actions">
      <q-btn
        flat
        dense
        no-caps
        size="sm"
        color="primary"
        :label="$t('settings_assistant_rule_open')"
        data-test="settings-assistant-rule-open"
        @click="$emit('open-rule', rulePath)"
      />
      <template v-if="undoAvailable">
        <q-btn
          flat
          dense
          no-caps
          size="sm"
          color="primary"
          :label="$t('undo')"
          :loading="undoing"
          :disable="undoing"
          data-test="settings-assistant-rule-undo"
          @click="undoRule"
        />
        <span
          class="sa-rule-entry__countdown"
          data-test="settings-assistant-rule-undo-countdown"
          >{{ $t('settings_assistant_rule_undo_remaining', { time: remainingText }) }}</span
        >
      </template>
    </div>

    <p
      v-if="!creation.undone && expired && !errorKey"
      class="sa-rule-entry__status"
      data-test="settings-assistant-rule-undo-expired"
    >
      {{ $t('settings_assistant_rule_undo_expired') }}
    </p>

    <p
      v-if="errorKey"
      class="sa-rule-entry__error"
      role="alert"
      data-test="settings-assistant-rule-undo-error"
    >
      {{ $t(errorKey) }}
    </p>
  </div>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import { Icon } from '@iconify/vue';
import settingsAssistantRuleService, {
  RuleRequestError,
} from 'src/services/settingsAssistant/settingsAssistantRuleService';
import {
  useSettingsAssistantConversationStore,
  type RuleCreation,
} from 'src/store/SettingsAssistant/settings_assistant_conversation.store';
import { useTrRulesSyncStore } from 'src/store/Settings/tr-rules-sync.store';
import { getOrgId } from 'src/utils/organization/org_id_helper';

const COUNTDOWN_TICK_MS = 1_000;

/** undo() failure → the entry's message. A 409 means somebody edited,
 * activated or deleted the rule since — never silently undone. */
export function undoErrorKey(err: unknown): string {
  const status = err instanceof RuleRequestError ? err.status : undefined;
  switch (status) {
    case 409:
      return 'settings_assistant_rule_undo_changed';
    case 404:
    case 410:
      return 'settings_assistant_rule_undo_expired';
    case 403:
      return 'settings_assistant_rule_admin_only';
    case 503:
      return 'settings_assistant_rule_error_unavailable';
    default:
      return 'settings_assistant_rule_undo_error';
  }
}

export default defineComponent({
  name: 'SettingsAssistantRuleCreatedEntry',

  components: { Icon },

  props: {
    creation: {
      type: Object as PropType<RuleCreation>,
      required: true,
    },
    /** The transcript text ("Regel angelegt (inaktiv): <Name>"). */
    content: {
      type: String,
      default: '',
    },
  },

  emits: ['open-rule'],

  setup() {
    return {
      conversationStore: useSettingsAssistantConversationStore(),
      rulesSync: useTrRulesSyncStore(),
    };
  },

  data() {
    return {
      nowMs: Date.now(),
      tick: null as ReturnType<typeof setInterval> | null,
      undoing: false,
      errorKey: '' as string,
      /** A 409/410 ends the undo offer for good — the server said no. */
      undoRefused: false,
    };
  },

  computed: {
    rulePath(): string {
      return `/settings/transformation-rules/${encodeURIComponent(
        this.creation.docType,
      )}/${encodeURIComponent(this.creation.ruleId)}`;
    },

    remainingMs(): number {
      return Math.max(0, this.creation.expiresAt - this.nowMs);
    },

    expired(): boolean {
      return this.remainingMs <= 0;
    },

    undoAvailable(): boolean {
      return !this.creation.undone && !this.expired && !this.undoRefused;
    },

    /** mm:ss */
    remainingText(): string {
      const totalSeconds = Math.floor(this.remainingMs / 1000);
      const minutes = Math.floor(totalSeconds / 60);
      const seconds = totalSeconds % 60;
      return `${minutes}:${String(seconds).padStart(2, '0')}`;
    },
  },

  mounted() {
    if (this.undoAvailable) {
      this.tick = setInterval(() => {
        this.nowMs = Date.now();
        if (!this.undoAvailable) this.stopTick();
      }, COUNTDOWN_TICK_MS);
    }
  },

  beforeUnmount() {
    this.stopTick();
  },

  methods: {
    stopTick() {
      if (this.tick) clearInterval(this.tick);
      this.tick = null;
    },

    async undoRule() {
      if (this.undoing || !this.undoAvailable) return;
      this.errorKey = '';
      // The countdown only re-renders once a second — re-check the real
      // deadline right before the call.
      this.nowMs = Date.now();
      if (this.expired) return;
      if (getOrgId() !== this.creation.orgIdAtCreate) {
        this.errorKey = 'settings_assistant_apply_undo_wrong_org';
        return;
      }
      this.undoing = true;
      try {
        const result = await settingsAssistantRuleService.undo(
          this.creation.operationId,
        );
        if (!result.undone && !result.applied) {
          this.errorKey = 'settings_assistant_rule_undo_error';
          return;
        }
        this.conversationStore.markRuleUndone(this.creation.operationId);
        this.rulesSync.notifyChanged({
          docType: result.doc_type || this.creation.docType,
          ruleId: this.creation.ruleId,
          kind: 'undone',
        });
        this.stopTick();
      } catch (err) {
        this.errorKey = undoErrorKey(err);
        const status = err instanceof RuleRequestError ? err.status : undefined;
        if (status === 409 || status === 410 || status === 404) {
          this.undoRefused = true;
          this.stopTick();
        }
      } finally {
        this.undoing = false;
      }
    },
  },
});
</script>

