import { translated, type Translate } from 'src/utils/translate';
import {
  aiModelDisplayLabel,
  isAiModelSettingKey,
  looksLikeAiModelId,
} from 'src/utils/settingsAssistant/aiModelDisplay';

/**
 * CORE-6108 review (Codex, #16844): SettingsAssistantPanel.vue's
 * `formatRecValue` and SettingsAssistantApplyDialog.vue's `formatValue`
 * each had their own copy of this formatting, with the same two bugs:
 *
 *  1. Any string that LOOKED like "0"/"1"/"true"/"false" was rendered as
 *     an/aus (on/off) unconditionally — wrong for a genuinely numeric or
 *     enum setting that happens to hold the string "1" (e.g. a retry
 *     count), which showed as "an" instead of "1".
 *  2. Neither function had an object branch, so an object value (or an
 *     object nested inside an array) fell through to `String(value)` =
 *     "[object Object]".
 *
 * The API contract (deep_links.py / chat_guardrails.validate_recommendations,
 * see AssistantRecommendation's own doc comment in settingsAssistantService.
 * ts) does not send a `value_type` field today — `valueType` here is
 * forward-compatible with a future backend addition, but a value is ONLY
 * formatted as boolean when `valueType === 'bool'` OR it is already a real
 * JS `boolean`, never by guessing from a string's contents. Absent a
 * `valueType`, a string is only ever treated as a Tolgee label (falling
 * back to itself) or, for objects/arrays, formatted structurally — never
 * coerced to on/off.
 */
export type RecommendationValueType = 'bool' | 'number' | 'enum' | string;

/** "0"/"false" -> false, "1"/"true" -> true (case/whitespace-insensitive);
 * anything else falls back to plain JS truthiness. Only reached once the
 * caller already knows (via `valueType === 'bool'` or a real `boolean`)
 * that this value IS a boolean — a bare string alone never triggers this. */
function isTruthyBoolLike(value: unknown): boolean {
  if (typeof value === 'string') {
    const normalized = value.trim().toLowerCase();
    if (normalized === '0' || normalized === 'false') return false;
    if (normalized === '1' || normalized === 'true') return true;
  }
  return Boolean(value);
}

export function formatRecommendationValue(
  value: unknown,
  t: Translate,
  valueType?: RecommendationValueType,
  settingKey?: string | null,
): string {
  if (value === null || value === undefined || value === '') {
    return String(t('settings_assistant_apply_value_unset'));
  }

  // Lists first: a 'bool' list formats each entry, not the list itself.
  if (Array.isArray(value)) {
    if (!value.length) {
      return String(t('settings_assistant_apply_value_unset'));
    }
    return value
      .map((entry) =>
        formatRecommendationValue(entry, t, valueType, settingKey),
      )
      .join(', ');
  }

  if (
    typeof value === 'boolean' ||
    (valueType === 'bool' && typeof value !== 'object')
  ) {
    return String(t(isTruthyBoolLike(value) ? 'on' : 'off'));
  }

  if (typeof value === 'object') {
    const entries = Object.entries(value as Record<string, unknown>);
    if (!entries.length) {
      return String(t('settings_assistant_apply_value_unset'));
    }
    // No valueType passed through for nested values — an object's OWN
    // fields aren't independently typed by the (currently nonexistent)
    // contract; each is formatted by its own JS type instead.
    return entries
      .map(
        ([key, entryValue]) =>
          `${key}: ${formatRecommendationValue(entryValue, t)}`,
      )
      .join(', ');
  }

  if (typeof value === 'string') {
    // CORE-6108: an AI model setting (or any value shaped like a model id)
    // shows its tier name — never the internal id, and an unknown id gets a
    // neutral label instead of itself.
    if (isAiModelSettingKey(settingKey) || looksLikeAiModelId(value)) {
      return aiModelDisplayLabel(value, t);
    }
    // valueType === 'enum' (or absent/unknown) — try the value as a Tolgee
    // key (catalog enum labels are keys by contract), falling back to the
    // raw string itself.
    return translated(t, value, value);
  }

  // number, or anything else JS can stringify directly.
  return String(value);
}
