/**
 * CORE-6108 review — a confirmed/undone apply-flow value needs to land in
 * the SAME two store slots every caller mirrors it into: `org_based_settings`
 * always, and `user_settings` UNLESS the user has their own override
 * (`user_based_settings[key]`) — many bound components (e.g.
 * QR_extraction.vue) read the setting via `user_settings[KEY]`, not
 * `org_based_settings[KEY]` directly, so skipping the first half leaves the
 * UI showing the stale pre-change value even though the write succeeded.
 *
 * SettingsAssistantApplyDialog.vue's own `updateStoreValue` had the
 * user_settings write right from CORE-6109; the transcript line's own
 * "Rückgängig" path (SettingsLayout.vue's `undoAppliedChange`, added by
 * CORE-6108) originally only wrote `org_based_settings` — a real drift bug,
 * not a hypothetical one. Both now call this one function instead of
 * keeping two copies of the same lines in sync by hand.
 *
 * CORE-6108 review round 2: the ORIGINAL dialog code (and this function's
 * first cut) used a truthiness check — `!stores.user_based_settings[key]` —
 * to decide "no override". That's wrong for an override whose value is
 * itself falsy: a user who explicitly overrode a boolean setting to
 * `false` has `user_based_settings[key] === false`, and `!false` is
 * `true`, so the override was silently treated as absent and overwritten
 * anyway. A presence check is the only correct test for "does an override
 * exist", independent of what value it holds.
 */
export interface SettingStoreSlots {
  user_settings: Record<string, unknown>;
  org_based_settings: Record<string, unknown>;
  user_based_settings: Record<string, unknown>;
}

export function updateSettingStoreValue(
  stores: SettingStoreSlots,
  settingKey: string,
  value: unknown,
): void {
  const hasUserOverride = Object.prototype.hasOwnProperty.call(
    stores.user_based_settings,
    settingKey,
  );
  if (!hasUserOverride) {
    stores.user_settings[settingKey] = value;
  }
  stores.org_based_settings[settingKey] = value;
}
