<template>
  <AssistantShell
    :overlay="overlay"
    :width="conversationStore.panelWidth"
    :aria-label="$t('settings_assistant_title')"
    test-id="settings-assistant"
  >
    <!-- CORE-6108: side-by-side mode only; the overlay drawer keeps a fixed width -->
    <template v-if="!overlay" #grip>
      <AssistantResizeGrip
        :model-value="conversationStore.panelWidth"
        :min="minPanelWidth"
        :max="maxPanelWidth"
        test-id="settings-assistant"
        @update:model-value="conversationStore.setPanelWidth($event)"
        @reset="conversationStore.resetPanelWidth()"
      />
    </template>

    <template #header>
      <AssistantHeader
        :title="$t('settings_assistant_title')"
        :new-chat-disabled="isStreaming || !turns.length"
        test-id="settings-assistant"
        @new-chat="startNewChat"
        @close="$emit('close')"
      />
    </template>

    <AssistantMessageList ref="messageList" test-id="settings-assistant">
      <!-- CORE-6145: an import channel this org set up has stopped working. -->
      <SettingsAssistantHealthNotice
        @open-settings="openRule"
        @ask="ask($event)"
        @dismissed="focusInput"
      />
      <!-- CORE-6108: on a known settings page the greeting names it and offers its questions -->
      <div
        v-if="!turns.length && !isStreaming && !unavailable && currentPageQuestions"
        class="settings-assistant__empty-state"
        data-test="settings-assistant-page-intro"
      >
        <p
          class="settings-assistant__empty-greeting"
          data-test="settings-assistant-page-greeting"
        >
          {{ pageGreetingParts[0]
          }}<strong data-test="settings-assistant-page-title">{{
            currentPageTitle
          }}</strong
          >{{ pageGreetingParts[1] }}
          {{ pageGreetingOffer }}
        </p>
        <AssistantExampleChips
          :items="pageQuestionChips"
          test-id="settings-assistant"
          @pick="onPageQuestionPick"
        />
        <p
          class="settings-assistant__page-other text-muted-foreground"
          data-test="settings-assistant-page-other"
        >
          {{ $t('settings_assistant_page_greeting_other') }}
        </p>
      </div>

      <div
        v-else-if="!turns.length && !isStreaming && !unavailable"
        class="settings-assistant__empty-state"
        data-test="settings-assistant-intro"
      >
        <p class="settings-assistant__empty-greeting">
          {{ $t('settings_assistant_intro') }}
        </p>
        <p class="settings-assistant__empty-capabilities-heading">
          {{ $t('settings_assistant_capabilities_heading') }}
        </p>
        <ul class="settings-assistant__empty-capabilities">
          <li>
            <Icon icon="mdi:check" width="14" height="14" class="text-primary shrink-0" />
            <span>{{ $t('settings_assistant_capability_locate') }}</span>
          </li>
          <li>
            <Icon icon="mdi:check" width="14" height="14" class="text-primary shrink-0" />
            <span>{{ $t('settings_assistant_capability_check') }}</span>
          </li>
          <li>
            <Icon icon="mdi:check" width="14" height="14" class="text-primary shrink-0" />
            <span>{{ $t('settings_assistant_capability_screenshots') }}</span>
          </li>
          <li>
            <Icon icon="mdi:check" width="14" height="14" class="text-primary shrink-0" />
            <span>{{ $t('settings_assistant_capability_apply') }}</span>
          </li>
        </ul>
        <AssistantExampleChips
          :items="exampleQuestionChips"
          test-id="settings-assistant"
          @pick="askExample($event.key)"
        />
      </div>

      <q-btn v-if="videoAvailable" class="f-btn my-2" flat :disable="isStreaming || !canRetryVideo" :label="$t('settings_assistant.video.watch')" data-test="settings-assistant-video-watch" @click="watchPageVideo" />
      <AssistantBubble
        v-for="(turn, idx) in turns"
        :key="idx"
        :role="turn.role"
        :content="turn.content"
        :render-markdown="renderTurnMarkdown"
        copyable
        test-id="settings-assistant"
      >
        <!-- CORE-6103: a rule created from a preview card, with "Zur Regel" and its undo countdown -->
        <template v-if="turn.role === 'system' && turn.ruleCreation" #default>
          <SettingsAssistantRuleCreatedEntry
            :creation="turn.ruleCreation"
            :content="turn.content"
            @open-rule="openRule"
          />
        </template>
        <!-- an applied change; the undo action itself is SettingsLayout's slot -->
        <template v-else-if="turn.role === 'system'" #default>
          <AssistantAppliedChangeLine
            :content="turn.content"
            :undone="!!turn.undone"
            :expires-at="typeof turn.expiresAt === 'number' ? turn.expiresAt : null"
            :now-ms="nowMs"
            test-id="settings-assistant"
          >
            <template #action>
              <slot name="applied-change-action" :turn="turn"></slot>
            </template>
          </AssistantAppliedChangeLine>
        </template>

        <!-- order per turn: answer, rule preview, recommendation cards, apply offer last -->
        <template #after>
          <SettingsAssistantPageVideoCard v-if="turn.pageVideo && idx !== videoRetryIndex" :video="turn.pageVideo" :ui-locale="currentLanguage()" />
          <q-btn v-if="turn.role === 'user' && turn.videoRetry && idx === turns.length - 1" class="f-btn" flat :disable="isStreaming || !canRetryVideo" :label="$t('settings_assistant.video.retry')" @click="runVideoTurn(turn.videoRetry, turn.content)" />
          <p v-if="turn.videoUnavailable && !turn.pageVideo">{{ $t('settings_assistant.video.unavailable') }}</p>
          <div v-if="turn.origin === 'page_video' && turn.role === 'assistant' && turn.completion !== 'complete'">
            <p>{{ $t('settings_assistant.video.interrupted') }}</p>
            <q-btn v-if="turn.videoRetry" class="f-btn" flat :disable="isStreaming || !canRetryVideo" :label="$t('settings_assistant.video.retry')" @click="retryPageVideo(idx)" />
          </div>
          <div v-if="turn.rulePreview" class="mt-2">
            <SettingsAssistantRulePreviewCard
              :preview="turn.rulePreview"
              :created-rule-id="turn.ruleCreatedId || null"
            />
          </div>

          <!-- CORE-6145: one card per broken import connection, with switch-off / delete -->
          <div
            v-if="turn.importActions && turn.importActions.length"
            class="flex flex-col gap-3 mt-2"
            data-test="settings-assistant-import-actions"
          >
            <SettingsAssistantImportConnectionCard
              v-for="offer in turn.importActions"
              :key="`${offer.channel}:${offer.config_id}`"
              :offer="offer"
            />
          </div>

          <!-- CORE-6145: a change the admin asked for, carried out by their "Yes" -->
          <div
            v-if="turn.settingsActions && turn.settingsActions.length"
            class="flex flex-col gap-3 mt-2"
            data-test="settings-assistant-settings-actions"
          >
            <SettingsAssistantSettingsActionCard
              v-for="action in turn.settingsActions"
              :key="action.preview_id"
              :offer="action"
            />
          </div>

          <div
            v-if="turn.recommendations && turn.recommendations.length"
            class="flex flex-col gap-3 mt-2"
          >
            <div
              v-for="rec in turn.recommendations"
              :key="rec.id"
              class="settings-assistant__rec"
            >
              <AssistantActionCard
                data-test="settings-assistant-recommendation"
                :kicker="rec.label_key ? $t(rec.label_key) : ''"
                :title="rec.title || ''"
                :reason="rec.reason || ''"
                :meta="rec.measured || ''"
                :current-value="
                  hasCurrentValue(rec)
                    ? formatRecValue(rec.current_value, rec.value_type, rec.setting_key)
                    : null
                "
                test-id="settings-assistant"
              >
                <template v-if="rec.breadcrumb && rec.breadcrumb.length" #header>
                  <nav
                    class="settings-assistant__breadcrumb"
                    data-test="settings-assistant-breadcrumb"
                    :aria-label="$t('settings_assistant_breadcrumb_label')"
                  >
                    <template v-for="(crumb, cIdx) in rec.breadcrumb" :key="cIdx">
                      <span
                        v-if="cIdx > 0"
                        class="settings-assistant__breadcrumb-sep"
                        aria-hidden="true"
                        >/</span
                      >
                      <span class="settings-assistant__breadcrumb-item">{{
                        $t(crumb)
                      }}</span>
                    </template>
                  </nav>
                </template>

                <!-- no images: nothing rendered, not even an empty gap -->
                <div
                  v-if="recommendationImages(rec).length"
                  class="settings-assistant__images"
                  data-test="settings-assistant-images"
                >
                  <button
                    v-for="(img, iIdx) in recommendationImages(rec)"
                    :key="iIdx"
                    v-show="!brokenImages.has(img.url) && !tinyImages.has(img.url)"
                    type="button"
                    class="settings-assistant__thumb"
                    :aria-label="img.alt"
                    @click="openLightbox(img, $event)"
                  >
                    <img
                      :src="img.url"
                      :alt="img.alt"
                      loading="lazy"
                      @error="onImageError(img.url)"
                      @load="onImageLoad(img.url, $event)"
                    />
                  </button>
                </div>

                <!-- the path is only acted on once resolveDeepLink accepts it; a button so the anchor jump can follow -->
                <template
                  v-if="resolveDeepLink(rec) || (rec.doc_url && isDocsUrl(rec.doc_url))"
                  #actions
                >
                  <q-btn
                    v-if="resolveDeepLink(rec)"
                    unelevated
                    color="primary"
                    no-caps
                    class="settings-assistant__action-btn settings-assistant__action-btn--primary"
                    data-test="settings-assistant-deep-link"
                    @click="goToSetting(rec)"
                    >{{ $t('settings_assistant_open_setting') }}</q-btn
                  >
                  <a
                    v-if="rec.doc_url && isDocsUrl(rec.doc_url)"
                    :href="rec.doc_url"
                    target="_blank"
                    rel="noopener noreferrer"
                    class="settings-assistant__doc-link"
                    data-test="settings-assistant-doc-link"
                  >
                    <Icon icon="mdi:book-open-variant" width="14" height="14" />
                    {{ $t('settings_assistant_doc_link') }}
                  </a>
                </template>
              </AssistantActionCard>

              <!-- display: contents, so an empty slot adds no gap -->
              <div class="settings-assistant__apply-offer">
                <slot name="recommendation-action" :recommendation="rec"></slot>
              </div>
            </div>
          </div>

          <div
            v-if="turn.sources && turn.sources.length"
            class="settings-assistant__sources"
            data-test="settings-assistant-sources"
          >
            <span class="text-xs text-muted-foreground">{{
              $t('settings_assistant_sources')
            }}</span>
            <template v-for="src in turn.sources" :key="src.url">
              <a
                v-if="isDocsUrl(src.url)"
                :href="src.url"
                target="_blank"
                rel="noopener noreferrer"
                class="text-xs text-primary"
                >{{ src.title }}</a
              >
              <template v-if="isDocsUrl(src.url) && src.videos && src.videos.length">
                <q-btn
                  v-for="video in src.videos"
                  :key="video.url"
                  class="f-btn"
                  flat
                  dense
                  no-caps
                  :label="$t('settings_assistant.video.watch')"
                  :title="video.title"
                  data-test="settings-assistant-docs-video-watch"
                  @click="toggleDocsVideo(docsVideoKey(idx, src.url, video.url))"
                />
                <template v-for="video in src.videos" :key="video.url">
                  <video
                    v-if="openDocsVideoKey === docsVideoKey(idx, src.url, video.url)"
                    class="aspect-video w-full"
                    controls
                    playsinline
                    preload="none"
                    :src="video.url"
                    :aria-label="video.title"
                    data-test="settings-assistant-docs-video"
                  />
                </template>
              </template>
            </template>
          </div>
        </template>
      </AssistantBubble>

      <!-- after the turns: it is the reply to the last question -->
      <div
        v-if="unavailable"
        class="settings-assistant__notice border border-border"
        data-test="settings-assistant-unavailable"
      >
        <Icon
          icon="mdi:progress-wrench"
          width="32"
          height="32"
          class="text-muted-foreground"
        />
        <p class="font-semibold">
          {{ $t('settings_assistant_unavailable_title') }}
        </p>
        <p class="text-muted-foreground text-sm">
          {{ $t('settings_assistant_unavailable_text') }}
        </p>
      </div>

      <SettingsAssistantPageVideoCard v-if="pendingVideo" :video="pendingVideo" :ui-locale="currentLanguage()" />
      <AssistantStreamingBubble
        v-if="isStreaming"
        :text="streamingText"
        :status-label="streamingStatusLabel"
        :render-markdown="renderTurnMarkdown"
        test-id="settings-assistant"
        @stop="stopStreaming"
      />

      <AssistantErrorNotice
        v-if="error"
        :message="errorText"
        :trace-id="error.traceId"
        :retryable="!!error.retryable"
        :retry-disabled="!canRetryNow"
        test-id="settings-assistant"
        @retry="retry"
      />
    </AssistantMessageList>

    <template #footer>
      <!-- CORE-6108: in a running conversation a chip still offers help for the current page -->
      <div
        v-if="turns.length && currentPageQuestions && !isStreaming && !unavailable"
        class="settings-assistant__page-help"
      >
        <button
          type="button"
          class="settings-assistant__page-help-chip"
          data-test="settings-assistant-page-help-chip"
          @click="askPageHelp"
        >
          <Icon icon="mdi:help-circle-outline" width="14" height="14" />
          {{ $t('settings_assistant_page_help_chip') }}
        </button>
      </div>

      <AssistantComposer
        ref="composer"
        v-model="draft"
        :placeholder="$t('settings_assistant_placeholder')"
        :disabled="isStreaming || unavailable"
        test-id="settings-assistant"
        @submit="send"
      />

      <AssistantImageLightbox
        v-model="lightboxOpen"
        :image="lightboxImage"
        :caption="lightboxCaption"
        test-id="settings-assistant"
        @hide="onLightboxHide"
      />
    </template>
  </AssistantShell>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import SettingsAssistantPageVideoCard from './SettingsAssistantPageVideoCard.vue';
import { hasPublishedVideo, normalizeVideoLanguage, normalizeVideoPage, parsePageVideoFrame, type PageVideo, type VideoRetry, type VideoOutcome } from 'src/utils/settingsAssistant/pageVideos';
import { parseDocsVideos } from 'src/utils/settingsAssistant/docsVideos';
import { conversationScope } from 'src/store/SettingsAssistant/settings_assistant_conversation.store';
import { Icon } from '@iconify/vue';
import { useTolgee } from '@tolgee/vue';
import { renderAssistantMarkdown } from 'src/utils/settingsAssistant/assistantMarkdown';
import {
  isSettingsAssistantDocsUrl,
  isSettingsAssistantImageUrl,
} from 'src/constants';
import { jumpToAnchor } from 'src/utils/settingsAssistant/anchorHighlight';
import { isResolvableAppPath } from 'src/utils/settingsAssistant/resolvableAppPath';
import { formatRecommendationValue } from 'src/utils/settingsAssistant/formatRecommendationValue';
import { sanitizeAiModelIds } from 'src/utils/settingsAssistant/aiModelDisplay';
import {
  resolveSettingsPage,
  settingsPageParams,
  type SettingsPageQuestions,
} from 'src/utils/settingsAssistant/settingsPageGreeting';
import SettingsAssistantRulePreviewCard from 'src/components/SettingsAssistant/SettingsAssistantRulePreviewCard.vue';
import SettingsAssistantHealthNotice from 'src/components/SettingsAssistant/SettingsAssistantHealthNotice.vue';
import SettingsAssistantRuleCreatedEntry from 'src/components/SettingsAssistant/SettingsAssistantRuleCreatedEntry.vue';
import AssistantShell from 'src/components/AssistantChat/AssistantShell.vue';
import AssistantResizeGrip from 'src/components/AssistantChat/AssistantResizeGrip.vue';
import AssistantHeader from 'src/components/AssistantChat/AssistantHeader.vue';
import AssistantMessageList from 'src/components/AssistantChat/AssistantMessageList.vue';
import AssistantBubble from 'src/components/AssistantChat/AssistantBubble.vue';
import AssistantStreamingBubble from 'src/components/AssistantChat/AssistantStreamingBubble.vue';
import AssistantErrorNotice from 'src/components/AssistantChat/AssistantErrorNotice.vue';
import AssistantExampleChips, {
  type AssistantExampleChip,
} from 'src/components/AssistantChat/AssistantExampleChips.vue';
import AssistantComposer from 'src/components/AssistantChat/AssistantComposer.vue';
import AssistantActionCard from 'src/components/AssistantChat/AssistantActionCard.vue';
import AssistantAppliedChangeLine from 'src/components/AssistantChat/AssistantAppliedChangeLine.vue';
import AssistantImageLightbox from 'src/components/AssistantChat/AssistantImageLightbox.vue';
import {
  isRulePreview,
  type RulePreview,
} from 'src/services/settingsAssistant/settingsAssistantRuleService';
import SettingsAssistantSettingsActionCard from 'src/components/SettingsAssistant/SettingsAssistantSettingsActionCard.vue';
import SettingsAssistantImportConnectionCard from 'src/components/SettingsAssistant/SettingsAssistantImportConnectionCard.vue';
import {
  parseImportActionOffers,
  type ImportActionOffer,
} from 'src/utils/settingsAssistant/importActionOffers';
import {
  parseSettingsActionOffers,
  type SettingsActionOffer,
} from 'src/utils/settingsAssistant/settingsActionOffers';
import settingsAssistantService, {
  AssistantUnavailableError,
  AssistantRequestError,
  AssistantStreamTimeoutError,
  type AssistantImage,
  type AssistantRecommendation,
  type AssistantSource,
  type AssistantTurn,
  type AssistantRequest,
} from 'src/services/settingsAssistant/settingsAssistantService';
import {
  useSettingsAssistantConversationStore,
  MIN_PANEL_WIDTH,
  panelWidthMax,
  type ConversationTurn,
} from 'src/store/SettingsAssistant/settings_assistant_conversation.store';

type PanelTurn = ConversationTurn;

/** CORE-6108 (PO feedback): a couple of clickable example questions in the
 * empty state — filling and sending the draft rather than the user having to
 * type from a blank input. Plain translation keys, not backend content. */
const EXAMPLE_QUESTION_KEYS = [
  'settings_assistant_example_barcode',
  'settings_assistant_example_po_matching',
  'settings_assistant_example_email_import',
];

/** Stand-in for the page title inside the translated greeting sentence, so
 * the title can be rendered bold wherever a language puts it. */
const PAGE_TITLE_SLOT = '\u0000';

/** The API caps `messages` at 20 (422 above that) — the server tracks the
 * rest of the history itself via `conversation_id`. */
const MAX_MESSAGES_SENT = 20;

/** How often the applied-change countdown / retry-after cooldown re-render.
 * Coarse on purpose — a "~N min left" label doesn't need per-second ticks. */
const TICK_INTERVAL_MS = 5_000;

/**
 * CORE-6108 UX review — a progressive "what I'm doing right now" label for
 * an optional `{type:"status", step:"..."}` SSE chunk. Nothing in the
 * verified `AssistantChunk` union (settingsAssistantService.ts) declares
 * this chunk type yet — it's speculative, forward-compatible handling, not
 * a confirmed part of the wire contract. readAssistantStream already yields
 * any parsed JSON chunk as-is, so this build simply never matches an
 * unknown/future step and falls back to the generic "Denkt nach …" label,
 * the exact same tolerant behaviour it already has for any other unknown
 * `chunk.type`.
 */
const STATUS_STEP_KEYS: Record<string, string> = {
  reading_config: 'settings_assistant_status_reading_config',
  searching_docs: 'settings_assistant_status_searching_docs',
  writing: 'settings_assistant_status_writing',
  // CORE-6103 — the rule turn on a transformation-rules page
  // (doc2-api helpers/settings_assistant/rule_chat.py).
  reading_rules: 'settings_assistant_status_reading_rules',
  drafting_rule: 'settings_assistant_status_drafting_rule',
  testing_samples: 'settings_assistant_status_testing_samples',
};

/** A screenshot smaller than this in either dimension reads as a broken/
 * placeholder asset, not a real screenshot — hidden the same as a hard
 * image error (CORE-6108 UX review). */
const MIN_SCREENSHOT_DIMENSION_PX = 200;

export default defineComponent({
  name: 'SettingsAssistantPanel',

  components: {
    SettingsAssistantPageVideoCard,
    Icon,
    SettingsAssistantHealthNotice,
    SettingsAssistantRulePreviewCard,
    SettingsAssistantRuleCreatedEntry,
    AssistantShell,
    AssistantResizeGrip,
    AssistantHeader,
    AssistantMessageList,
    AssistantBubble,
    AssistantStreamingBubble,
    AssistantErrorNotice,
    AssistantExampleChips,
    AssistantComposer,
    AssistantActionCard,
    AssistantAppliedChangeLine,
    AssistantImageLightbox,
    SettingsAssistantImportConnectionCard,
    SettingsAssistantSettingsActionCard,
  },

  props: {
    /** The settings page the user is on; sent as context with every question. */
    page: {
      type: String,
      required: true,
    },
    /**
     * CORE-6108 review: <1280px the drawer overlays the content instead of
     * sitting beside it — while it does, it must behave as a true modal
     * dialog (role="dialog" + aria-modal, a focus trap, inert background),
     * not merely a complementary panel someone can tab past.
     */
    overlay: {
      type: Boolean,
      default: false,
    },
  },

  emits: ['close'],

  setup() {
    // CORE-6108: turns/draft/panel-width now live in a Pinia store (a
    // singleton for the app's lifetime), not this component's own data() —
    // see settings_assistant_conversation.store.ts for why. Returned here
    // (CLAUDE.md: setup() is allowed for calling composables/stores) and
    // used via `this.conversationStore` everywhere below; the rest of the
    // component stays Options API.
    const conversationStore = useSettingsAssistantConversationStore();
    // CORE-6108 review: `$i18n.locale` (vue-i18n, src/boot/i18n.js) is
    // seeded ONCE from navigator.language at boot and never updated again —
    // it is NOT the app's actual active language. That's Tolgee's own
    // (src/boot/tolgee.js: selected_language / the backend PREFERRED_LANGUAGE
    // setting / the language picker), read here the same way
    // MainLayout.vue and Sub-Header.vue already do.
    //
    // CORE-6108 review round 2: only the composable call belongs here —
    // the raw handle is returned as-is; the `locale` computed that reads it
    // lives in the Options API `computed` block below (CLAUDE.md: "do not
    // move computed... logic into setup()").
    const tolgee = useTolgee(['language']);
    return { conversationStore, tolgee };
  },

  data() {
    return {
      isStreaming: false,
      openDocsVideoKey: null as string | null,
      streamingText: '',
      pendingVideo: null as PageVideo | null,
      videoRetryIndex: null as number | null,
      unavailable: false,
      error: null as null | {
        traceId: string;
        retryable?: boolean;
        /** 'rate_limited' (429) | 'forbidden' (403) | 'unavailable' (503) —
         * everything else falls back to the generic/timeout messages. */
        kind?: 'rate_limited' | 'forbidden' | 'unavailable';
      },
      abort: null as AbortController | null,
      lastQuestionHistory: null as null | AssistantTurn[],
      /** CORE-6103: the chip intent of the last question, kept for retry. */
      lastQuestionIntent: undefined as AssistantRequest['intent'],
      lightboxOpen: false,
      lightboxImage: null as AssistantImage | null,
      // CORE-6108 UX review: the element that opened the lightbox
      // (a thumbnail button) — focus returns to it on close instead of
      // being dropped to <body>.
      lightboxTriggerEl: null as HTMLElement | null,
      brokenImages: new Set<string>(),
      // CORE-6108 UX review: a screenshot that loaded but is suspiciously
      // tiny (a broken/placeholder asset, not a real screenshot) is treated
      // the same as a hard image error — hidden, never shown stretched or
      // pixelated at thumbnail size.
      tinyImages: new Set<string>(),
      exampleQuestionKeys: EXAMPLE_QUESTION_KEYS,
      // {type:"status", step} chunks — tolerantly ignored if step isn't one
      // of the labels this build knows how to translate.
      streamingStatusStep: null as string | null,
      // A 429's Retry-After — the retry button stays disabled until this
      // timestamp. 0 = no cooldown in effect.
      retryDisabledUntil: 0,
      // Ticks every TICK_INTERVAL_MS so the applied-change countdown and the
      // retry-after cooldown re-evaluate without a per-second timer.
      nowMs: Date.now(),
      tickInterval: null as ReturnType<typeof setInterval> | null,
      // CORE-6108 review: `window.innerWidth` read directly inside a
      // computed is NOT a Vue reactive dependency — maxPanelWidth would
      // silently go stale after a real window resize (aria-valuemax, the
      // End-key target, and the reclamp below all inherit that value).
      // Mirrors SettingsLayout.vue's own windowWidth+debounce pattern.
      windowWidth: typeof window !== 'undefined' ? window.innerWidth : 1440,
      windowResizeTimer: null as ReturnType<typeof setTimeout> | null,
    };
  },

  computed: {
    videoAvailable(): boolean { return !this.unavailable && hasPublishedVideo((this.$route?.path || this.page)); },
    /** Tolgee's own active language (see the setup() comment above) —
     * kept as an Options API computed reading the raw `tolgee` handle
     * setup() returns, not a computed() constructed inside setup() itself. */
    locale(): string {
      return this.tolgee.getLanguage() || 'en';
    },

    /** Read-only view of the store's turns — mutations always go through
     * conversationStore actions (addTurn/clearConversation), never a direct
     * push here, so persistence and the MAX_TURNS cap can never be bypassed. */
    turns(): PanelTurn[] {
      return this.conversationStore.turns as PanelTurn[];
    },

    /** A plain computed with a setter so `v-model="draft"` keeps working
     * unchanged while the value itself now lives in the store. */
    draft: {
      get(): string {
        return this.conversationStore.draft;
      },
      set(value: string) {
        this.conversationStore.setDraft(value);
      },
    },

    minPanelWidth(): number {
      return MIN_PANEL_WIDTH;
    },

    maxPanelWidth(): number {
      return panelWidthMax(this.windowWidth);
    },

    /** Status-specific translated messages for the well-known cases; the
     * existing timeout/generic fallback otherwise. */
    errorText(): string {
      if (!this.error) return '';
      if (this.error.kind === 'rate_limited') {
        return String(this.$t('settings_assistant_rate_limited'));
      }
      if (this.error.kind === 'forbidden') {
        return String(this.$t('settings_assistant_forbidden'));
      }
      if (this.error.kind === 'unavailable') {
        return String(this.$t('settings_assistant_unavailable_retry'));
      }
      return String(
        this.$t(
          this.error.retryable
            ? 'settings_assistant_timeout'
            : 'settings_assistant_error',
        ),
      );
    },

    canRetryVideo(): boolean {
      return !this.unavailable && this.canRetryNow && this.error?.retryable !== false;
    },

    /** False while a 429's Retry-After cooldown is still running. Reads
     * `nowMs` (not Date.now() directly) so the ticking interval below is
     * what makes the button re-enable itself without a user action. */
    canRetryNow(): boolean {
      return this.nowMs >= this.retryDisabledUntil;
    },

    /** A translated progress label for the current `{type:"status", step}`
     * chunk, or '' for an unrecognised/absent step — the caller falls back
     * to the generic "Denkt nach …" either way, so an unknown step is a
     * silent no-op, never a broken label. */
    /** CORE-6108: the settings page the panel is shown on, or null for the
     * hub/unknown pages (generic greeting). Follows `page` reactively. */
    currentPageQuestions(): SettingsPageQuestions | null {
      return resolveSettingsPage(this.page);
    },

    currentPageTitle(): string {
      const entry = this.currentPageQuestions;
      return entry ? String(this.$t(entry.titleKey)) : '';
    },

    /** "Du bist gerade auf {page}." split around the title, so the title can
     * be bold without v-html, in whatever position a language puts it. */
    pageGreetingParts(): [string, string] {
      const sentence = String(
        this.$t('settings_assistant_page_greeting', { page: PAGE_TITLE_SLOT }),
      );
      const idx = sentence.indexOf(PAGE_TITLE_SLOT);
      if (idx < 0) return [sentence + ' ', ''];
      return [sentence.slice(0, idx), sentence.slice(idx + PAGE_TITLE_SLOT.length)];
    },

    /** CORE-6103: the page's own offer ("Soll ich dir helfen, eine neue
     * Transformationsregel für INVOICE anzulegen?") with its route params,
     * or the generic one. */
    pageGreetingOffer(): string {
      const entry = this.currentPageQuestions;
      if (entry?.greetingKey) {
        return String(
          this.$t(entry.greetingKey, settingsPageParams(entry.route, this.page)),
        );
      }
      return String(this.$t('settings_assistant_page_greeting_offer'));
    },

    pageQuestionChips(): AssistantExampleChip[] {
      const keys = this.currentPageQuestions?.questionKeys || [];
      return keys.map((key, qIdx) => ({
        key,
        label: String(this.$t(key)),
        primary: this.isPrimaryQuestion(qIdx),
        dataTest: this.isPrimaryQuestion(qIdx)
          ? 'settings-assistant-page-primary-chip'
          : 'settings-assistant-page-question-chip',
      }));
    },

    exampleQuestionChips(): AssistantExampleChip[] {
      return this.exampleQuestionKeys.map((key) => ({
        key,
        label: String(this.$t(key)),
      }));
    },

    lightboxCaption(): string {
      if (!this.lightboxImage?.alt) return '';
      return String(
        this.$t({
          key: 'settings_assistant_screenshot_caption',
          params: {
            label: this.lightboxImage.alt,
            language: this.currentLanguage().toUpperCase(),
          },
        }),
      );
    },

    streamingStatusLabel(): string {
      if (!this.streamingStatusStep) return '';
      const key = STATUS_STEP_KEYS[this.streamingStatusStep];
      return key ? String(this.$t(key)) : '';
    },
  },

  watch: {
    // Shown videos follow the UI language.
    locale() {
      this.swapPageVideoLocale();
    },
  },

  mounted() {
    // Drives the applied-change "N min left" label and the retry-after
    // cooldown — both compare against `nowMs` rather than `Date.now()`
    // directly so they're reactive without a per-second timer.
    this.tickInterval = setInterval(() => {
      this.nowMs = Date.now();
    }, TICK_INTERVAL_MS);
    window.addEventListener('resize', this.handleWindowResize);
  },

  beforeUnmount() {
    this.abort?.abort();
    window.removeEventListener('resize', this.handleWindowResize);
    if (this.tickInterval) clearInterval(this.tickInterval);
    if (this.windowResizeTimer) clearTimeout(this.windowResizeTimer);
  },

  methods: {
    /** The assistant's own markdown renderer (isolated Marked/DOMPurify
     * instances — never the shared src/utils/markdown.ts renderer DocNet's
     * issue/comment views depend on, CORE-6108 review). A relative link in
     * the answer TEXT gets the same router-resolution check as a
     * recommendation's app_path; a bare docs URL is relabelled to a short
     * translated title instead of a raw link (PO feedback). */
    renderTurnMarkdown(text: string): string {
      // CORE-6108: last layer — no internal AI model id reaches the chat,
      // however the model phrased it; each id becomes its tier name.
      return renderAssistantMarkdown(sanitizeAiModelIds(text, this.$t), {
        isValidRelativePath: this.isResolvableAppPath,
        docLinkLabel: String(this.$t('settings_assistant_doc_link')),
      });
    },

    /** CORE-6108: called by SettingsLayout when the drawer opens, so keyboard
     * focus lands in the composer rather than being left on the toggle. */
    focusInput() {
      (this.$refs.composer as { focus?: () => void } | undefined)?.focus?.();
    },

    /** Only docs.docbits.com may be opened from a chat answer — the backend
     * contract says sources/doc links always point there, but the panel
     * never trusts that without checking the host, protocol, credentials
     * and port itself (CORE-6108 review). */
    /** One player per (turn, source, video): the same video url under another
     * source or in another turn is a different player. */
    docsVideoKey(turnIdx: number, sourceUrl: string, videoUrl: string): string {
      return `${turnIdx}|${sourceUrl}|${videoUrl}`;
    },
    toggleDocsVideo(key: string) {
      this.openDocsVideoKey = this.openDocsVideoKey === key ? null : key;
    },
    isDocsUrl(url: string | undefined): boolean {
      return !!url && isSettingsAssistantDocsUrl(url);
    },

    /** Preserve the full UI tag for requests; screenshot maps use their own base fallback. */
    currentLanguage(): string {
      return normalizeVideoLanguage(this.locale || 'de');
    },

    /** Only the settings-assistant image allowlist may ever render as an
     * <img> (docs.docbits.com, the GitBook assets CDN, the screenshots
     * bucket under its fixed path prefix) — defence in depth on top of the
     * backend's own allowlist. */
    recommendationImages(rec: AssistantRecommendation): AssistantImage[] {
      // The API sends catalog screenshots per language ({ de: url|null,
      // en: url|null }); docs images come as a list. Accept both shapes —
      // calling .filter on the object form threw during render and the
      // whole panel unmounted mid-answer.
      const raw = rec.images as unknown;
      let images: AssistantImage[] = [];
      if (Array.isArray(raw)) {
        images = raw as AssistantImage[];
      } else if (raw && typeof raw === 'object') {
        const byLang = raw as Record<string, string | null | undefined>;
        const lang = this.currentLanguage().split('-')[0];
        const url = byLang[lang] || byLang.de || byLang.en;
        if (url) images = [{ url, alt: rec.label_key || rec.setting_key || '' }];
      }
      return images.filter(
        (img) =>
          img && img.url && img.alt && isSettingsAssistantImageUrl(img.url),
      );
    },

    onImageError(url: string) {
      this.brokenImages.add(url);
    },

    /** CORE-6108 UX review: a thumbnail that DID load but is suspiciously
     * tiny is almost always a broken/placeholder asset (a 1x1 tracking
     * pixel, a stub file), never a real screenshot — hidden the same as a
     * hard error rather than shown stretched or pixelated at thumbnail
     * size. */
    onImageLoad(url: string, event: Event) {
      const img = event.target as HTMLImageElement | null;
      if (!img) return;
      if (
        img.naturalWidth < MIN_SCREENSHOT_DIMENSION_PX ||
        img.naturalHeight < MIN_SCREENSHOT_DIMENSION_PX
      ) {
        this.tinyImages.add(url);
      }
    },

    /** Whether a recommendation carries a current_value worth showing —
     * `false`/`0` are meaningful values (must show), only null/undefined
     * mean "the catalog doesn't know". */
    hasCurrentValue(rec: AssistantRecommendation): boolean {
      return rec.current_value !== undefined && rec.current_value !== null;
    },

    /**
     * CORE-6108 UX review — the card used to show the raw stored value
     * verbatim ("Aktuell: 1" for a boolean the catalog happened to
     * serialise as the string "1"). Delegates to the shared
     * formatRecommendationValue (src/utils/settingsAssistant/
     * formatRecommendationValue.ts) — SettingsAssistantApplyDialog.vue's
     * own formatValue had the same "[object Object]"/boolish-string bugs
     * and now shares this one implementation instead of drifting again
     * (Codex review, 2026-09-29): boolean → translated on/off (only for a
     * real JS boolean or `rec.value_type === 'bool'`, never guessed from a
     * string), object (incl. nested in an array) → a "key: value" list
     * instead of "[object Object]", array → each entry formatted the same
     * way and comma-joined, any other string → a translated option label
     * if one exists for that exact raw value, else the raw string.
     */
    formatRecValue(
      value: unknown,
      valueType?: string,
      settingKey?: string,
    ): string {
      return formatRecommendationValue(value, this.$t, valueType, settingKey);
    },

    openLightbox(img: AssistantImage, event?: Event) {
      this.lightboxTriggerEl = (event?.currentTarget as HTMLElement) || null;
      this.lightboxImage = img;
      this.lightboxOpen = true;
    },

    /** CORE-6108 UX review: q-dialog's own @hide fires on every close path
     * (the new close button, Quasar's built-in Escape handling, and a
     * backdrop click alike) — focus returns to the thumbnail that opened
     * it instead of being dropped to <body>. */
    onLightboxHide() {
      this.lightboxTriggerEl?.focus();
      this.lightboxTriggerEl = null;
    },

    /**
     * A path is only ever acted on once it: starts with exactly one '/'
     * (rejects absolute URLs, protocol-relative "//host" links, and
     * "javascript:" — none of those match a leading single slash), AND
     * resolves via the app's own router to a real route rather than the
     * catch-all 404. Shared by resolveDeepLink (recommendation buttons) and
     * renderTurnMarkdown (relative links inside the answer's own text).
     */
    isResolvableAppPath(path: string): boolean {
      return isResolvableAppPath(this.$router, path);
    },

    /**
     * A recommendation's link is only ever rendered once isResolvableAppPath
     * confirms it. `app_path` is the current field name; `deep_link` is kept
     * as a fallback for the currently-deployed server (PR #16800's
     * compatibility shim emits both with the same value). Returns the path
     * or null.
     */
    resolveDeepLink(rec: AssistantRecommendation | undefined): string | null {
      const path = rec?.app_path || rec?.deep_link;
      if (!path || !this.isResolvableAppPath(path)) return null;
      return path;
    },

    /** "Zur Einstellung": in-app navigation (drawer stays open, outside
     * <router-view>), then — once the target page has actually mounted —
     * find the exact control, expand whatever accordion hides it, scroll to
     * it and briefly highlight it.
     *
     * Overlay mode (<1280px, Codex r2): the panel is a modal there and the
     * page behind it is `inert`, so the highlighted control could never
     * take focus while the panel stays open. The panel closes itself first
     * (same `close` the header button emits); jumpToAnchor then waits for
     * `inert` to clear before focusing the control. The router is captured
     * up front because closing unmounts this component. */
    async goToSetting(rec: AssistantRecommendation) {
      const path = this.resolveDeepLink(rec);
      if (!path) return;
      const router = this.$router;
      if (this.overlay) this.$emit('close');
      await router.push(path);
      await jumpToAnchor(rec.anchor);
    },

    /** CORE-6103 "Zur Regel": the created rule's edit page, in-app. Same
     * overlay handling as goToSetting — the panel closes first when it is
     * a modal overlay, so the page behind it is usable. */
    async openRule(path: string) {
      if (!this.isResolvableAppPath(path)) return;
      const router = this.$router;
      if (this.overlay) this.$emit('close');
      await router.push(path);
    },

    scrollToBottom() {
      (this.$refs.messageList as { scrollToBottom?: () => void } | undefined)?.scrollToBottom?.();
    },

    /** CORE-6108 review: keeps `windowWidth` (and therefore maxPanelWidth /
     * aria-valuemax / the End-key target) in sync with the real viewport,
     * and reclamps the current panelWidth if it now exceeds the new max
     * (e.g. the window was made narrower). Debounced the same way
     * SettingsLayout.vue's own handleResize is. */
    handleWindowResize() {
      if (this.windowResizeTimer) clearTimeout(this.windowResizeTimer);
      this.windowResizeTimer = setTimeout(() => {
        this.windowWidth = window.innerWidth;
        const max = panelWidthMax(this.windowWidth);
        if (this.conversationStore.panelWidth > max) {
          this.conversationStore.setPanelWidth(max);
        }
      }, 150);
    },

    async watchPageVideo() {
      if (!this.videoAvailable || this.isStreaming || !this.canRetryVideo) return;
      const page = normalizeVideoPage(this.$route?.path || this.page);
      if (!page) return;
      const snapshot: VideoRetry = {
        page,
        locale: this.currentLanguage(),
        intent: 'page_video',
      };
      const content = String(this.$t('settings_assistant.video.watch'));
      this.conversationStore.addTurn({
        role: 'user',
        content,
        origin: 'page_video',
        videoRetry: snapshot,
      });
      await this.runVideoTurn(snapshot, content);
    },
    async retryPageVideo(index: number) {
      if (this.isStreaming || !this.canRetryVideo) return;
      const turn = this.turns[index];
      if (!turn?.videoRetry) return;
      await this.runVideoTurn(
        turn.videoRetry,
        String(this.$t('settings_assistant.video.watch')),
        index,
      );
    },
    async runVideoTurn(
      snapshot: VideoRetry,
      content: string,
      replaceIndex?: number,
    ) {
      if (this.isStreaming || !this.canRetryVideo) return;
      this.error = null;
      this.isStreaming = true;
      this.pendingVideo = null;
      this.streamingText = '';
      this.lastQuestionHistory = null;
      this.videoRetryIndex = replaceIndex ?? null;
      const controller = new AbortController();
      this.abort = controller;
      const scope = conversationScope();
      const conversationId = this.conversationStore.conversationId;
      const current = () =>
        scope === conversationScope() &&
        conversationId === this.conversationStore.conversationId;
      let video: PageVideo | null = null;
      let traceId: string | undefined;
      let outcome: VideoOutcome | undefined;
      let done = false;
      let streamError = false;
      let requestFailed = false;
      let completion: 'complete' | 'interrupted' | 'error' = 'interrupted';
      try {
        for await (const chunk of settingsAssistantService.chat(
          {
            page: snapshot.page,
            language: snapshot.locale,
            intent: 'page_video',
            messages: [{ role: 'user', content }],
            conversation_id: conversationId,
          },
          controller.signal,
          () => {
            done = true;
          },
        )) {
          if (!current()) {
            controller.abort();
            break;
          }
          if (controller.signal.aborted) break;
          const trace = chunk.trace_id || chunk.docbits_trace_id;
          if (traceId && trace && traceId !== trace)
            throw new Error('Video trace changed');
          if (trace) traceId = trace;
          if (chunk.type === 'page_video') {
            const parsed = parsePageVideoFrame(chunk);
            if (video || outcome || !parsed)
              throw new Error('Invalid or duplicate video');
            video = parsed.video;
            this.pendingVideo = video;
          } else if (chunk.type === 'outcome') {
            if (
              outcome ||
              !['answered', 'nothing_found', 'error'].includes(chunk.outcome) ||
              !chunk.trace_id ||
              chunk.trace_id !== chunk.docbits_trace_id
            )
              throw new Error('Invalid video outcome');
            outcome = chunk.outcome as VideoOutcome;
          } else if (chunk.type === 'text') {
            if (video || outcome) throw new Error('Unexpected video text');
            this.streamingText += chunk.delta;
          } else if (chunk.type === 'error') {
            if (outcome || streamError) throw new Error('Unexpected video error');
            streamError = true;
          } else {
            throw new Error('Unexpected video frame');
          }
          this.scrollToBottom();
        }
        if (
          !controller.signal.aborted &&
          !streamError &&
          done &&
          ((video && outcome === 'answered') ||
            (!video && outcome === 'nothing_found'))
        )
          completion = 'complete';
        else if (streamError || outcome === 'error') completion = 'error';
      } catch (err) {
        completion =
          (err as Error)?.name === 'AbortError' ? 'interrupted' : 'error';
        if (current() && completion === 'error') {
          requestFailed = true;
          this.handleRequestError(err);
        }
      } finally {
        if (current() && (video || this.streamingText)) {
          const response: ConversationTurn = {
            role: 'assistant',
            content: this.streamingText,
            origin: 'page_video',
            completion,
            videoRetry: snapshot,
            ...(video ? { pageVideo: video } : {}),
            ...(traceId ? { traceId } : {}),
            ...(outcome ? { terminalOutcome: outcome } : {}),
          };
          if (replaceIndex !== undefined) {
            this.conversationStore.turns.splice(replaceIndex, 1, response);
            this.conversationStore.persistConversation();
          } else this.conversationStore.addTurn(response);
        } else if (current() && !controller.signal.aborted && !requestFailed) {
          this.error = { traceId: traceId || '', retryable: true };
        }
        this.pendingVideo = null;
        this.videoRetryIndex = null;
        this.streamingText = '';
        this.isStreaming = false;
        this.abort = null;
      }
    },

    /** Re-requests each shown video in the UI language; a failed swap keeps the old card. */
    async swapPageVideoLocale() {
      const locale = this.currentLanguage();
      for (let index = 0; index < this.turns.length; index++) {
        if (this.isStreaming || !this.canRetryVideo) return;
        const turn = this.turns[index];
        if (
          turn.role !== 'assistant' ||
          !turn.pageVideo ||
          !turn.videoRetry ||
          turn.videoRetry.locale === locale
        )
          continue;
        await this.runVideoTurn(
          { ...turn.videoRetry, locale },
          String(this.$t('settings_assistant.video.watch')),
          index,
        );
      }
    },

    handleRequestError(err: unknown) {
      if (err instanceof AssistantUnavailableError) {
        this.unavailable = true;
      } else if (err instanceof AssistantStreamTimeoutError) {
        this.error = { traceId: '', retryable: true };
      } else if (err instanceof AssistantRequestError) {
        // CORE-6108 review: 429/403/503 used to all fall through to the
        // same generic "something went wrong" — 429 and 503 are actually
        // retryable (a rate limit or a transient outage, not a real
        // failure), and 403 means "you're not an admin", not "broken".
        if (err.status === 429) {
          this.error = { traceId: err.traceId, retryable: true, kind: 'rate_limited' };
          this.retryDisabledUntil = err.retryAfterMs
            ? Date.now() + err.retryAfterMs
            : 0;
        } else if (err.status === 403) {
          this.error = { traceId: err.traceId, retryable: false, kind: 'forbidden' };
        } else if (err.status === 503) {
          this.error = { traceId: err.traceId, retryable: true, kind: 'unavailable' };
        } else {
          this.error = { traceId: err.traceId };
        }
      } else {
        this.error = { traceId: '' };
      }
    },

    async runTurn(history: AssistantTurn[], intent?: AssistantRequest['intent']) {
      this.error = null;
      this.isStreaming = true;
      this.streamingText = '';
      this.streamingStatusStep = null;
      const sources: AssistantSource[] = [];
      const recommendations: AssistantRecommendation[] = [];
      let rulePreview: RulePreview | null = null;
      let importActions: ImportActionOffer[] = [];
      let settingsActions: SettingsActionOffer[] = [];
      this.abort = new AbortController();
      this.lastQuestionHistory = history;
      this.lastQuestionIntent = intent;
      this.scrollToBottom();

      try {
        for await (const chunk of settingsAssistantService.chat(
          {
            page: this.page,
            messages: history,
            language: this.currentLanguage(),
            conversation_id: this.conversationStore.conversationId,
            ...(intent ? { intent } : {}),
          },
          this.abort.signal,
        )) {
          if (chunk.type === 'text') this.streamingText += chunk.delta;
          else if (chunk.type === 'source') {
            const videos = parseDocsVideos(chunk.videos);
            sources.push({
              title: chunk.title,
              url: chunk.url,
              ...(videos.length ? { videos } : {}),
            });
          }
          else if (chunk.type === 'recommendation')
            recommendations.push(chunk.recommendation);
          else if ((chunk as { type: string }).type === 'rule_preview') {
            // CORE-6103 — validated before it is ever rendered; a malformed
            // payload is dropped, never half-drawn as a card.
            const payload = (chunk as { rule_preview?: unknown }).rule_preview;
            if (isRulePreview(payload)) rulePreview = payload;
          } else if ((chunk as { type: string }).type === 'import_actions') {
            // CORE-6145 — each offer is validated; a malformed item is
            // dropped, never half-drawn as a card.
            importActions = parseImportActionOffers(
              (chunk as { items?: unknown }).items,
            );
          } else if ((chunk as { type: string }).type === 'settings_actions') {
            // CORE-6145 — validated like the import offers above.
            settingsActions = parseSettingsActionOffers(
              (chunk as { items?: unknown }).items,
            );
          } else if ((chunk as { type: string }).type === 'status') {
            // Speculative, forward-compatible: NOT part of the verified
            // AssistantChunk union today (see STATUS_STEP_KEYS' own doc
            // comment) — a cast, not a widened type, and an unrecognised
            // `step` value just renders nothing extra (streamingStatusLabel
            // falls back to the generic "Denkt nach …").
            const step = (chunk as { type: string; step?: unknown }).step;
            this.streamingStatusStep = typeof step === 'string' ? step : null;
          }
          this.scrollToBottom();
        }
        this.persistAssistantTurn(
          sources,
          recommendations,
          rulePreview,
          importActions,
          settingsActions,
        );
      } catch (err: unknown) {
        if ((err as { name?: string })?.name === 'AbortError') {
          // Stop (or unmount) mid-answer: keep whatever already streamed in
          // as a normal assistant turn — the admin may already have read
          // the half that answers their question, and it was wiping itself
          // the moment they clicked Stop (Codex review, 2026-09-29). An
          // abort before anything arrived (token/auth phase) adds nothing;
          // the user's own question turn stays either way.
          this.persistAssistantTurn(
            sources,
            recommendations,
            rulePreview,
            importActions,
            settingsActions,
          );
          return;
        }
        this.handleRequestError(err);
      } finally {
        this.isStreaming = false;
        this.streamingText = '';
        this.streamingStatusStep = null;
        this.abort = null;
        this.scrollToBottom();
      }
    },

    /** Adds the streamed answer (text + sources + recommendations collected
     * so far) as an assistant turn, if anything arrived at all. Shared by
     * the normal end-of-stream path and the Stop/AbortError path. */
    persistAssistantTurn(
      sources: AssistantSource[],
      recommendations: AssistantRecommendation[],
      rulePreview: RulePreview | null = null,
      importActions: ImportActionOffer[] = [],
      settingsActions: SettingsActionOffer[] = [],
    ) {
      if (
        !this.streamingText &&
        !sources.length &&
        !recommendations.length &&
        !rulePreview &&
        !importActions.length &&
        !settingsActions.length
      ) {
        return;
      }
      this.conversationStore.addTurn({
        role: 'assistant',
        content: this.streamingText,
        sources,
        recommendations,
        ...(rulePreview ? { rulePreview } : {}),
        ...(importActions.length ? { importActions } : {}),
        ...(settingsActions.length ? { settingsActions } : {}),
      });
      this.lastQuestionHistory = null;
    },

    /** CORE-6108 UX review — a Stop button next to the thinking indicator:
     * aborts the in-flight stream (same signal `beforeUnmount` already
     * uses) and re-enables the input immediately, rather than making the
     * user wait out a slow/stuck answer. Whatever text streamed in before
     * Stop is pressed is KEPT as an assistant turn (see runTurn's
     * AbortError branch); an abort during the token/auth phase ends
     * immediately too (settingsAssistantService races the token fetch
     * against the same signal).
     *
     * Codex review (2026-09-29): Stop used to leave focus wherever it was
     * (on the Stop button itself, which then unmounts once `isStreaming`
     * flips back to false — the focus is silently dropped to <body>).
     * The composer is `:disable="isStreaming || unavailable"`, and
     * `abort()` here only *starts* the unwind of the in-flight `for
     * await` loop in `runTurn` — its `finally` (which clears
     * `isStreaming`) runs some indeterminate number of microtasks later,
     * not synchronously and not necessarily by the next Vue tick. A
     * one-shot `$watch` on `isStreaming` (rather than a fixed number of
     * `$nextTick`s) focuses the composer exactly once it's actually
     * enabled again, however long the unwind takes; already-idle (the
     * stream finished in the same instant Stop was clicked) is handled
     * as its own case since the watcher would never otherwise fire.
     */
    stopStreaming() {
      this.abort?.abort();
      if (!this.isStreaming) {
        this.$nextTick(() => this.focusInput());
        return;
      }
      const stopWatchingStream = this.$watch(
        () => this.isStreaming,
        (streaming) => {
          if (streaming) return;
          stopWatchingStream();
          this.$nextTick(() => this.focusInput());
        },
      );
    },

    /** The composer's send (form submit / Enter). Never takes an argument
     * from the template — a DOM event must not end up as the chip intent. */
    async send() {
      await this.sendDraft();
    },

    /** Sends the draft as the user's question; `intent` only from a page
     * chip (askPageQuestion). */
    async sendDraft(intent?: AssistantRequest['intent']) {
      const question = this.draft.trim();
      if (!question || this.isStreaming || this.unavailable) return;

      this.conversationStore.addTurn({ role: 'user', content: question });
      this.draft = '';
      // System turns (applied-change transcript lines) are UI-only, never
      // part of the LLM conversation. The API caps `messages` at 20 (422
      // above that) — the server tracks the rest via conversation_id, so
      // only the tail needs to be resent.
      const history: AssistantTurn[] = this.turns
        .filter(
          (t): t is PanelTurn & { role: 'user' | 'assistant' } =>
            (t.role === 'user' || t.role === 'assistant') && t.origin !== 'page_video' && !t.pageVideo,
        )
        .map((t) => ({ role: t.role, content: t.content }))
        .slice(-MAX_MESSAGES_SENT);
      await this.runTurn(history, intent);
    },

    /** A clickable example question from the empty state: fills the draft
     * and sends it immediately, same as if the user had typed and pressed
     * enter (PO feedback). */
    async askExample(key: string) {
      await this.ask(String(this.$t(key)));
    },

    /** "Hilfe zu dieser Seite" in a running conversation: asks the generic
     * page question — the API answers it about the page it receives. */
    async askPageHelp() {
      await this.ask(String(this.$t('settings_assistant_page_help_question')));
    },

    async ask(question: string, intent?: AssistantRequest['intent']) {
      if (this.isStreaming || this.unavailable) return;
      this.draft = question;
      await this.sendDraft(intent);
    },

    /** CORE-6103: the first question of a page with a `primaryIntent` is
     * that page's primary action. */
    isPrimaryQuestion(index: number): boolean {
      return index === 0 && !!this.currentPageQuestions?.primaryIntent;
    },

    onPageQuestionPick(item: AssistantExampleChip) {
      const keys = this.currentPageQuestions?.questionKeys || [];
      return this.askPageQuestion(item.key, keys.indexOf(item.key));
    },

    /** A page-greeting chip: the primary one carries its intent. */
    async askPageQuestion(key: string, index: number) {
      const intent = this.isPrimaryQuestion(index)
        ? this.currentPageQuestions?.primaryIntent
        : undefined;
      await this.ask(String(this.$t(key)), intent);
    },

    /** "Neuer Chat": an intentional, user-initiated reset — distinct from
     * the accidental wipes the conversation store exists to prevent.
     * Disabled (see the template) while a stream is in flight, so there is
     * nothing to abort here — no surprise mid-stream cancellation, no
     * confirm dialog. Focus moves back into the composer, same as opening
     * the panel fresh. */
    startNewChat() {
      if (this.isStreaming || !this.turns.length) return;
      this.error = null;
      this.unavailable = false;
      this.lastQuestionHistory = null;
      this.openDocsVideoKey = null;
      this.conversationStore.clearConversation();
      this.$nextTick(() => this.focusInput());
    },

    /** Re-sends the same question after a retryable (timeout) failure —
     * without pushing a second user bubble, since the original question is
     * already the last turn. */
    async retry() {
      if (this.isStreaming) return;
      const last = this.turns[this.turns.length - 1];
      if (last?.origin === 'page_video' && last.videoRetry) {
        await this.runVideoTurn(last.videoRetry, last.role === 'user' ? last.content : String(this.$t('settings_assistant.video.watch')), last.role === 'assistant' ? this.turns.length - 1 : undefined);
        return;
      }
      if (!this.lastQuestionHistory) return;
      await this.runTurn(this.lastQuestionHistory, this.lastQuestionIntent);
    },
  },
});
</script>

