<template>
  <!-- Visually hidden h1 for accessibility (WCAG page-has-heading-one) -->
  <h1 class="sr-only">{{ $t('settings') }}</h1>
  <SubHeader
    name="settings"
    :label="$t('settings')"
    :onSearch="false"
    :inert="assistantModalActive ? true : undefined"
  />

  <div class="settings-layout" data-test="settings-layout">
    <!-- Loading State -->
    <div v-if="isLoadingProfile" class="loading-container q-pa-xl text-center">
      <q-spinner-dots color="primary" size="50px" />
      <p class="q-mt-md text-grey-6">{{ $t('loading') || 'Loading...' }}</p>
    </div>

    <!-- Profile Load Error -->
    <div
      v-else-if="isProfileError"
      class="loading-container q-pa-xl text-center"
    >
      <q-icon name="wifi_off" size="80px" color="grey-6" />
      <h4 class="q-mt-md q-mb-sm text-grey-8">
        {{ $t('connection_error') || 'Connection Error' }}
      </h4>
      <p class="text-grey-6 q-mb-lg">
        {{
          $t('profile_load_failed') ||
          'Could not load your profile. Please try again.'
        }}
      </p>
      <q-btn
        color="primary"
        :label="$t('retry') || 'Retry'"
        @click="retryProfile"
        no-caps
      />
    </div>

    <!-- Admin Only Access Message -->
    <div
      v-else-if="!isAdmin && !isSupplier"
      class="access-denied-container"
      data-test="settings-access-denied"
    >
      <q-card class="access-denied-card text-center q-pa-xl">
        <q-icon name="admin_panel_settings" size="80px" color="grey-6" />
        <h4 class="q-mt-md q-mb-sm text-grey-8">
          {{ $t('admin_only_title') || 'Admin Access Required' }}
        </h4>
        <p class="text-grey-6 q-mb-lg">
          {{
            $t('admin_only_message') ||
            'Settings are only available for organization administrators. Please contact your administrator for access.'
          }}
        </p>
        <q-btn
          color="primary"
          :label="$t('back_to_dashboard') || 'Back to Dashboard'"
          @click="$router.push('/dashboard')"
          no-caps
        />
      </q-card>
    </div>

    <!--
      Main Settings Layout
      NOTE: Uses v-show instead of v-else to avoid a Vue 3 fragment patching bug.
      q-drawer uses Teleport internally, which breaks DOM insertion when switching
      v-if/v-else branches with 4+ conditions. v-show keeps the element in the DOM
      and avoids the detached-node issue entirely.
    -->
    <div
      v-show="!isLoadingProfile && !isProfileError && isAdmin"
      class="settings-layout-body"
      :class="{ 'settings-layout-body--collapsed': sidebarCollapsed }"
    >
      <!-- Mobile sidebar toggle -->
      <q-btn
        v-if="isMobileView"
        flat
        round
        dense
        icon="menu"
        class="sidebar-toggle"
        :inert="assistantModalActive ? true : undefined"
        @click="sidebarOpen = true"
      />

      <!-- Mobile: sidebar as drawer -->
      <q-drawer
        v-if="isMobileView"
        v-model="sidebarOpen"
        bordered
        side="left"
        :width="280"
        :breakpoint="0"
        overlay
        behavior="mobile"
      >
        <SettingsSidebar
          :inert="assistantModalActive ? true : undefined"
          :categories="categories"
          :active-route="$route.path"
          :assistant-available="assistantAvailable"
          :assistant-open="assistantPanelOpen"
          @item-click="sidebarOpen = false"
          @update:assistant-open="setAssistantPanelOpen($event)"
          @ask-assistant="askAssistant"
        />
      </q-drawer>

      <!-- Desktop: sidebar always visible -->
      <div
        v-if="!isMobileView"
        class="settings-sidebar-wrapper"
        :class="{ 'settings-sidebar-wrapper--resizing': sidebarResizing }"
        :style="!sidebarCollapsed ? { flexBasis: sidebarWidth + 'px' } : undefined"
      >
        <SettingsSidebar
          :categories="categories"
          :active-route="$route.path"
          :collapsed="sidebarCollapsed"
          :assistant-available="assistantAvailable"
          :assistant-open="assistantPanelOpen"
          :inert="assistantModalActive ? true : undefined"
          @update:collapsed="sidebarCollapsed = $event"
          @update:assistant-open="setAssistantPanelOpen($event)"
          @ask-assistant="askAssistant"
        />
        <div
          v-if="!sidebarCollapsed"
          class="settings-sidebar-grip"
          :class="{ 'settings-sidebar-grip--active': sidebarResizing }"
          role="separator"
          aria-orientation="vertical"
          tabindex="0"
          :aria-label="$t('settings_sidebar_resize_handle')"
          :aria-valuenow="sidebarWidth"
          :aria-valuemin="minSidebarWidth"
          :aria-valuemax="maxSidebarWidth"
          data-test="settings-sidebar-resize-handle"
          @pointerdown="onSidebarGripPointerDown"
          @keydown="onSidebarGripKeydown"
          @dblclick="setSidebarWidth(defaultSidebarWidth)"
        ></div>
      </div>

      <!-- Content area -->
      <div
        class="settings-content-area"
        data-test="settings-content-area"
        :inert="assistantModalActive ? true : undefined"
      >
        <router-view />
      </div>

      <!--
        CORE-6108: Settings-Assistent chat drawer, right side. >=1280px it is
        a flex sibling that pushes the content column (which always has
        flex:1/min-width:0, so it shrinks instead of overflowing); below that
        it overlays with a click-to-close scrim. Rendered only while open, so
        collapsed/hidden never affects layout at all — v-if, not v-show.
      -->
      <Transition name="settings-assistant-scrim">
        <div
          v-if="
            assistantAvailable && assistantPanelOpen && assistantOverlayViewport
          "
          class="settings-assistant-scrim"
          @click="setAssistantPanelOpen(false)"
        />
      </Transition>
      <Transition name="settings-assistant-drawer">
        <SettingsAssistantPanel
          v-if="assistantAvailable && assistantPanelOpen"
          id="settings-assistant-panel"
          ref="assistantPanelRef"
          :page="$route.path"
          :overlay="assistantOverlayViewport"
          class="settings-assistant-drawer"
          :class="{
            'settings-assistant-drawer--overlay': assistantOverlayViewport,
          }"
          @close="setAssistantPanelOpen(false)"
        >
          <!--
            CORE-6109: the "Übernehmen" action for a recommendation whose
            setting is in the Wave 1 apply catalog (apply_tool set). Kept
            here rather than inside SettingsAssistantPanel.vue itself — a
            different agent is working on that file (CORE-6108-deep-links)
            at the same time; the panel's own slot exists exactly for this.
            Admin-only client-side, mirroring the server's CORE-6104 guard
            (canWriteOrgPreferences) so the button is never offered where
            the API would refuse it anyway.

            Codex review (2026-09-29): this slot renders right after the
            panel's own "Zur Einstellung" button (settings-assistant__
            action-btn--primary, unelevated) when a card has BOTH a deep
            link and an apply_tool — two stacked `unelevated` buttons would
            compete for attention. `outline` keeps this one visually
            secondary, matching the "one filled action per card" rule
            documented next to `.settings-assistant__action-btn` in
            SettingsAssistantPanel.vue.
          -->
          <template #recommendation-action="{ recommendation }">
            <q-btn
              v-if="
                recommendation.apply_tool === 'apply_setting' &&
                recommendation.proposed_value !== null &&
                recommendation.proposed_value !== undefined &&
                canApplySettings
              "
              outline
              no-caps
              dense
              size="sm"
              color="primary"
              class="mt-1 self-start"
              :label="$t('settings_assistant_apply_button')"
              data-test="settings-assistant-apply-button"
              @click="openApplyDialog(recommendation)"
            />
          </template>

          <!--
            CORE-6108 review: an applied change's "Rückgängig" used to be
            offered ONLY on the confirm toast (notify.ts's default
            auto-dismiss, a few seconds) — the server-side undo window is
            far longer, but the UI affordance vanished long before it. This
            persistent transcript-line button is the same undo action,
            reachable for as long as the (client-estimated) undo window
            allows.
          -->
          <template #applied-change-action="{ turn }">
            <q-btn
              v-if="!turn.undone"
              flat
              dense
              no-caps
              color="primary"
              size="sm"
              class="settings-assistant-undo-btn"
              :label="$t('undo')"
              :loading="undoingChangeId === turn.undoId"
              :disable="undoingChangeId === turn.undoId"
              data-test="settings-assistant-applied-change-undo"
              @click="undoAppliedChange(turn)"
            />
          </template>
        </SettingsAssistantPanel>
      </Transition>

      <SettingsAssistantApplyDialog
        v-model="applyDialogOpen"
        :recommendation="applyDialogRecommendation"
        @applied="onRecommendationApplied"
        @undone="onRecommendationUndone"
      />
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import SubHeader from 'src/pages/Settings/Components/Sub-Header.vue';
import SettingsSidebar from 'src/pages/Settings/Components/SettingsSidebar.vue';
import {
  DEFAULT_SIDEBAR_WIDTH,
  MAX_SIDEBAR_WIDTH,
  MIN_SIDEBAR_WIDTH,
  SIDEBAR_RESIZE_KEYBOARD_STEP,
  clampSidebarWidth,
  persistSidebarWidth,
  readSidebarWidth,
} from 'src/utils/settingsSidebarWidth';
import SettingsAssistantPanel from 'src/components/SettingsAssistant/SettingsAssistantPanel.vue';
import SettingsAssistantApplyDialog, {
  type ApplyDialogRecommendation,
} from 'src/components/SettingsAssistant/SettingsAssistantApplyDialog.vue';
import { useSettingsNavigationStore } from 'src/store/settings-navigation';
import { useUserStore, useSettingStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import {
  isUserAdmin,
  isSupplierUser,
  getSupplierDetailsRoute,
} from 'src/utils/UserDetails';
import { canWriteOrgPreferences } from 'src/utils/preferences/canWriteOrgPreferences';
import {
  supplier_dashboard_setting,
  settings_assistant_enabled_setting,
  settings_assistant_panel_open_setting,
} from 'src/constants';
import { toBoolPreference } from 'src/utils/preferenceBool';
import { preferencesService } from 'src/services/preferences/preferencesService';
import { logger } from 'src/utils/logger';
import type { CategoryData } from 'src/@types/settings';
import { useSettingsAssistantConversationStore } from 'src/store/SettingsAssistant/settings_assistant_conversation.store';
import settingsAssistantApplyService from 'src/services/settingsAssistant/settingsAssistantApplyService';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import { notify } from 'src/components/notifications/notify';
import { updateSettingStoreValue } from 'src/utils/settingsAssistant/updateSettingStoreValue';

/** Quasar popups that own Escape while open (see handleAssistantKeydown). */
const ESCAPE_OWNING_POPUP_SELECTOR = '.q-dialog, .q-menu';

export default defineComponent({
  name: 'SettingsLayout',

  components: {
    SubHeader,
    SettingsSidebar,
    SettingsAssistantPanel,
    SettingsAssistantApplyDialog,
  },

  setup() {
    const navStore = useSettingsNavigationStore();
    const userStore = useUserStore();
    const settingStore = useSettingStore();
    // user_based_settings is needed here too now — undoAppliedChange
    // (CORE-6108 review) writes through the same updateSettingStoreValue
    // guard SettingsAssistantApplyDialog's own confirm/undo already use.
    const { user_settings, org_based_settings, user_based_settings } =
      storeToRefs(settingStore);
    // CORE-6108: the apply flow's @applied/@undone handlers below write an
    // applied-change transcript line into the same store the panel reads
    // its turns from.
    const conversationStore = useSettingsAssistantConversationStore();

    return {
      navStore,
      userStore,
      settingStore,
      user_settings,
      org_based_settings,
      user_based_settings,
      supplier_dashboard_setting,
      conversationStore,
    };
  },

  data() {
    return {
      isLoadingProfile: true,
      isAdmin: false,
      isSupplier: false,
      isProfileError: false,
      sidebarOpen: false,
      sidebarCollapsed: false,
      sidebarWidth: readSidebarWidth(),
      sidebarResizing: false,
      sidebarResizeStartX: 0,
      sidebarResizeStartWidth: 0,
      minSidebarWidth: MIN_SIDEBAR_WIDTH,
      maxSidebarWidth: MAX_SIDEBAR_WIDTH,
      defaultSidebarWidth: DEFAULT_SIDEBAR_WIDTH,
      // CORE-6108 — the undoId currently mid-flight from a transcript-line
      // "Rückgängig" click (disables/spins that one button only).
      undoingChangeId: null as string | null,
      // CORE-6108: per-user preference, defaults off, read once the profile
      // (and with it settingStore.user_settings) has loaded.
      assistantPanelOpen: false,
      // CORE-6108 review: write-coalescing state for setAssistantPanelOpen.
      latestRequestedPanelOpen: null as boolean | null,
      panelOpenWriteInFlight: false,
      windowWidth: window.innerWidth,
      resizeTimer: null as ReturnType<typeof setTimeout> | null,
      // CORE-6109 — the recommendation apply dialog, opened from the
      // panel's "Übernehmen" button (see the recommendation-action slot).
      applyDialogOpen: false,
      applyDialogRecommendation: null as ApplyDialogRecommendation | null,
    };
  },

  computed: {
    isMobileView(): boolean {
      return this.windowWidth < 768;
    },

    /**
     * CORE-6108 review (right-side drawer): below 1280px the drawer overlays
     * the content (with a click-to-close scrim) instead of sitting beside it
     * as a flex sibling — pushing a ~380px drawer at narrower widths left too
     * little room for the content and it overflowed the viewport.
     */
    assistantOverlayViewport(): boolean {
      return this.windowWidth < 1280;
    },

    /** CORE-6108 review: the panel is a true modal (overlay + open) — this
     * is what gates the background's `inert`. */
    assistantModalActive(): boolean {
      return (
        this.assistantOverlayViewport &&
        this.assistantAvailable &&
        this.assistantPanelOpen
      );
    },

    categories(): CategoryData[] {
      return this.navStore.getCategories(this.$t, {
        isAdmin: this.isAdmin,
        isSupplier: this.isSupplier,
        supplierDashboardEnabled: toBoolPreference(
          this.user_settings[this.supplier_dashboard_setting],
        ),
        supplierDetailsRoute: getSupplierDetailsRoute(),
      });
    },

    /** CORE-6108: org feature flag — without it the toggle isn't even shown. */
    assistantAvailable(): boolean {
      return toBoolPreference(
        this.org_based_settings[settings_assistant_enabled_setting],
      );
    },

    /** CORE-6109 — client-side mirror of the CORE-6104 server guard, so the
     * "Übernehmen" button is never shown where the API would refuse it. */
    canApplySettings(): boolean {
      return canWriteOrgPreferences();
    },
  },

  watch: {
    // Command palette deep link (?open=settings-assistant) works even when the
    // layout is already mounted — the query arrives on a route change.
    '$route.query.open': {
      handler(open: unknown) {
        if (open === 'settings-assistant') {
          this.setAssistantPanelOpen(true);
          this.$nextTick(() => this.focusPanelInputNextTick());
        }
      },
    },
    // Esc closes the panel from anywhere in the settings pages while it's
    // open; focus moves into the composer on open and back to the toggle
    // that opened it on close (CORE-6108 review).
    assistantPanelOpen(open: boolean) {
      if (open) {
        window.addEventListener('keydown', this.handleAssistantKeydown);
        this.focusPanelInputNextTick();
      } else {
        window.removeEventListener('keydown', this.handleAssistantKeydown);
        this.$nextTick(() => {
          const toggle = document.querySelector(
            '[data-test="settings-assistant-toggle"]',
          ) as HTMLElement | null;
          toggle?.focus();
        });
      }
    },

    /**
     * CORE-6108 review: the org feature flag (org_based_settings) can arrive
     * AFTER the user's own panel-open preference is already true — the panel
     * itself is v-if'd on `assistantAvailable && assistantPanelOpen`, so it
     * only actually mounts once this flips true. When that happens with the
     * panel already "open", focus must move into it now — the
     * assistantPanelOpen watcher above only fires on ITS OWN transitions,
     * never on this one.
     */
    assistantAvailable(available: boolean) {
      if (available && this.assistantPanelOpen) {
        this.focusPanelInputNextTick();
      }
    },

    /**
     * CORE-6108 review (Codex): resizing the viewport into overlay mode
     * (<1280px) while the panel is already open turns it into a modal —
     * focus must move INTO the trap right then, not stay wherever it was on
     * the (now-inert) page behind it.
     */
    assistantOverlayViewport(overlay: boolean) {
      if (overlay && this.assistantAvailable && this.assistantPanelOpen) {
        this.focusPanelInputNextTick();
      }
    },
  },

  async mounted() {
    window.addEventListener('resize', this.handleResize);

    try {
      await this.userStore.getProfile();
      this.isAdmin = isUserAdmin();
      this.isSupplier = isSupplierUser();
      // CORE-6108 review: getOrgSettings() clears user_settings to {} the
      // instant it starts and only repopulates it once its own fetch
      // resolves (setting.store.ts) — getProfile() kicks that fetch off
      // WITHOUT awaiting it, so reading user_settings right after
      // getProfile() resolves could still read the pre-clear OR the
      // mid-clear state. startSettingsFetch() is idempotent (it no-ops if
      // already loaded, or returns the same in-flight promise) — awaiting
      // it here guarantees user_settings is actually populated before the
      // preference read below.
      await this.settingStore.startSettingsFetch();
      this.assistantPanelOpen = toBoolPreference(
        this.user_settings[settings_assistant_panel_open_setting],
      );
      // Deep link from the command palette (?open=settings-assistant) opens
      // the assistant panel regardless of the stored preference.
      if (this.$route.query?.open === 'settings-assistant') {
        this.assistantPanelOpen = true;
        this.$nextTick(() => this.focusPanelInputNextTick());
      }
    } catch {
      this.isProfileError = true;
    } finally {
      this.isLoadingProfile = false;
    }
  },

  beforeUnmount() {
    window.removeEventListener('resize', this.handleResize);
    window.removeEventListener('keydown', this.handleAssistantKeydown);
    window.removeEventListener('pointermove', this.onSidebarGripPointerMove);
    window.removeEventListener('pointerup', this.onSidebarGripPointerUp);
    if (this.resizeTimer) clearTimeout(this.resizeTimer);
  },

  methods: {
    setSidebarWidth(px: number) {
      this.sidebarWidth = clampSidebarWidth(px);
      persistSidebarWidth(this.sidebarWidth);
    },

    onSidebarGripPointerDown(event: PointerEvent) {
      if (typeof event.button === 'number' && event.button !== 0) return;
      this.sidebarResizing = true;
      this.sidebarResizeStartX = event.clientX;
      this.sidebarResizeStartWidth = this.sidebarWidth;
      try {
        (event.currentTarget as HTMLElement | null)?.setPointerCapture?.(event.pointerId);
      } catch {
        // no pointer capture (jsdom); the window listeners still drive the drag
      }
      window.addEventListener('pointermove', this.onSidebarGripPointerMove);
      window.addEventListener('pointerup', this.onSidebarGripPointerUp, { once: true });
      event.preventDefault();
    },

    onSidebarGripPointerMove(event: PointerEvent) {
      if (!this.sidebarResizing) return;
      this.sidebarWidth = clampSidebarWidth(
        this.sidebarResizeStartWidth + event.clientX - this.sidebarResizeStartX,
      );
    },

    onSidebarGripPointerUp() {
      this.sidebarResizing = false;
      window.removeEventListener('pointermove', this.onSidebarGripPointerMove);
      persistSidebarWidth(this.sidebarWidth);
    },

    onSidebarGripKeydown(event: KeyboardEvent) {
      const steps: Record<string, number> = {
        ArrowRight: this.sidebarWidth + SIDEBAR_RESIZE_KEYBOARD_STEP,
        ArrowLeft: this.sidebarWidth - SIDEBAR_RESIZE_KEYBOARD_STEP,
        Home: MIN_SIDEBAR_WIDTH,
        End: MAX_SIDEBAR_WIDTH,
      };
      if (!(event.key in steps)) return;
      event.preventDefault();
      this.setSidebarWidth(steps[event.key]);
    },

    handleResize() {
      if (this.resizeTimer) clearTimeout(this.resizeTimer);
      this.resizeTimer = setTimeout(() => {
        this.windowWidth = window.innerWidth;
      }, 150);
    },

    /**
     * CORE-6108 UX review: pressing Esc to close the screenshot lightbox
     * (or the apply dialog, or any other q-dialog layered on top of the
     * panel) used to ALSO close the whole panel — Quasar's own q-dialog
     * closes itself on Escape, and this window-level listener fired on the
     * exact same keydown, closing the panel underneath it in the same
     * keystroke.
     *
     * Quasar's popups (QDialog AND QMenu — see
     * node_modules/quasar/src/utils/private.keyboard/escape-key.js) close
     * themselves on `keyup`, via a global handler stack Quasar owns; this
     * listener is on `keydown`, which the browser always dispatches FIRST
     * for the same physical keystroke. So at the moment this handler runs,
     * a popup that was open when the key was pressed is still in the DOM —
     * querying for it here is safe regardless of which of the two events
     * actually closes it later. A dialog/menu/listbox owns Esc while it's
     * open; the panel only reclaims it once nothing is layered on top —
     * exactly why a SECOND Esc (nothing left open) does close the panel.
     *
     * Codex review (2026-09-29): the original guard only checked
     * `.q-dialog` — a QSelect/QMenu dropdown left open over the panel (not
     * a dialog) fell through and the panel closed underneath it too.
     * `.q-menu` covers QMenu's root (QSelect's dropdown is a QMenu on
     * desktop, a QDialog on mobile). Both are portal-mounted only while
     * shown, so their mere presence means "open". A bare `[role="listbox"]`
     * is deliberately NOT part of the selector: static listboxes exist in
     * normal page markup and would disable Esc for good.
     */
    handleAssistantKeydown(event: KeyboardEvent) {
      if (event.key !== 'Escape') return;
      if (event.defaultPrevented) return;
      if (document.querySelector(ESCAPE_OWNING_POPUP_SELECTOR)) return;
      this.setAssistantPanelOpen(false);
    },

    focusPanelInputNextTick() {
      this.$nextTick(() => {
        const panel = this.$refs.assistantPanelRef as
          | { focusInput?: () => void }
          | undefined;
        panel?.focusInput?.();
      });
    },

    /**
     * CORE-6108: the panel's shown/hidden state is a per-USER preference
     * (never the org preference — those are admin-only and org-wide), so it
     * follows the admin across every /settings page and across logins.
     * Optimistic: the toggle applies immediately, persistence is best-effort.
     *
     * CORE-6108 review: writes are SERIALISED and COALESCED — only one
     * `setUserPreference` call is ever in flight. A fast open→close (a
     * second call arriving while the first is still in flight) no longer
     * risks the network reordering the two responses and persisting
     * "open" after the user's last action was "close": the loop below
     * always re-checks for a newer requested value and, if one arrived,
     * sends exactly one more request for THAT (latest) value once the
     * current one finishes — never two requests racing concurrently.
     */
    async askAssistant(question: string) {
      this.sidebarOpen = false;
      if (!this.assistantPanelOpen) this.setAssistantPanelOpen(true);
      await this.$nextTick();
      const panel = this.$refs.assistantPanelRef as { ask?: (q: string) => Promise<void> } | undefined;
      await panel?.ask?.(question);
    },

    async setAssistantPanelOpen(open: boolean) {
      this.assistantPanelOpen = open;
      this.user_settings[settings_assistant_panel_open_setting] = open;
      this.latestRequestedPanelOpen = open;
      if (this.panelOpenWriteInFlight) return;
      this.panelOpenWriteInFlight = true;
      try {
        while (this.latestRequestedPanelOpen !== null) {
          const value = this.latestRequestedPanelOpen;
          this.latestRequestedPanelOpen = null;
          const response = await preferencesService.setUserPreference(
            settings_assistant_panel_open_setting,
            value,
          );
          if (!response.success) {
            logger.warn(
              '[SettingsLayout] failed to persist settings-assistant panel visibility',
              response.error,
            );
          }
        }
      } finally {
        this.panelOpenWriteInFlight = false;
      }
    },

    /** CORE-6109 — opens the apply dialog for one recommendation card. The
     * dialog itself calls preview as soon as it opens (v-model watcher). */
    openApplyDialog(recommendation: ApplyDialogRecommendation) {
      this.applyDialogRecommendation = recommendation;
      this.applyDialogOpen = true;
    },

    /**
     * CORE-6108 review: the dialog's own `applied` event used to be
     * completely unhandled here — the only undo affordance was the confirm
     * toast's action button, gone the moment it auto-dismissed. Appends a
     * persistent transcript line to the conversation instead.
     */
    onRecommendationApplied(result: {
      setting_key: string;
      undo_id: string;
      label_key?: string;
      formattedNewValue?: string;
      /** Not on ApplyConfirmResult yet — an API PR is adding it. Read
       * defensively (unknown backend field, not a type this repo owns)
       * rather than assuming the shape. */
      expires_at?: string;
    }) {
      const label = result.label_key
        ? String(this.$t(result.label_key))
        : result.setting_key;
      const content = String(
        this.$t('settings_assistant_change_applied_line', {
          label,
          value: result.formattedNewValue ?? '',
        }),
      );
      const serverExpiresAt = result.expires_at
        ? Date.parse(result.expires_at)
        : NaN;
      this.conversationStore.addAppliedChangeTurn({
        content,
        undoId: result.undo_id,
        settingKey: result.setting_key,
        orgIdAtApply: getOrgId(),
        expiresAt: Number.isFinite(serverExpiresAt) ? serverExpiresAt : undefined,
      });
    },

    /** The dialog's OWN toast-triggered undo also went through
     * settingsAssistantApplyService.undo() — this only needs to mark the
     * matching transcript line so its "Rückgängig" button disappears too. */
    onRecommendationUndone(result: { undo_id: string }) {
      this.conversationStore.markChangeUndone(result.undo_id);
    },

    /**
     * The transcript line's OWN "Rückgängig" button — a second path to the
     * exact same undo call the dialog's toast action already made, for
     * exactly as long as the (client-estimated) undo window in the
     * conversation store says it should still be offered. Mirrors the
     * dialog's own org-switch guard (CORE-6108 review): the write happened
     * in `turn.orgIdAtApply`; undoing it only makes sense if that is still
     * the org currently in view.
     */
    async undoAppliedChange(turn: {
      undoId?: string;
      settingKey?: string;
      orgIdAtApply?: string;
      expiresAt?: number;
    }) {
      if (!turn.undoId || this.undoingChangeId) return;
      // CORE-6108 review: the panel's own template only re-checks
      // isChangeExpired() on its 5s tick — a click landing between ticks,
      // right as the window closes, could still reach here. Re-check the
      // absolute deadline right before the network call, not just trust
      // that the button wouldn't be visible if it had already expired.
      if (typeof turn.expiresAt === 'number' && Date.now() >= turn.expiresAt) {
        notify.info(this.$t('settings_assistant_undo_expired'));
        return;
      }
      if (getOrgId() !== turn.orgIdAtApply) {
        notify.info(this.$t('settings_assistant_apply_undo_wrong_org'));
        return;
      }
      this.undoingChangeId = turn.undoId;
      try {
        const result = await settingsAssistantApplyService.undo(turn.undoId);
        if (getOrgId() !== turn.orgIdAtApply) {
          notify.info(this.$t('settings_assistant_apply_org_changed'));
          return;
        }
        if (!result.applied || !result.verified) {
          notify.error(
            this.$t('settings_assistant_apply_error_undo'),
            this.$t('settings_assistant_apply_stale'),
          );
          return;
        }
        // Same store-write guard SettingsAssistantApplyDialog's own
        // confirm/undo use (CORE-6108 review: this path used to only write
        // org_based_settings, leaving components bound to user_settings —
        // e.g. QR_extraction.vue — showing the stale value).
        updateSettingStoreValue(
          {
            user_settings: this.user_settings,
            org_based_settings: this.org_based_settings,
            user_based_settings: this.user_based_settings,
          },
          result.setting_key,
          result.restored_value,
        );
        this.conversationStore.markChangeUndone(turn.undoId);
        notify.success(this.$t('settings_assistant_apply_undo_success'));
      } catch (err) {
        notify.error(
          this.$t('settings_assistant_apply_error_undo'),
          err instanceof Error ? err.message : String(this.$t('settings_assistant_error')),
        );
      } finally {
        this.undoingChangeId = null;
      }
    },

    async retryProfile() {
      this.isProfileError = false;
      this.isLoadingProfile = true;
      try {
        await this.userStore.getProfile();
        this.isAdmin = isUserAdmin();
        // CORE-6108 review: same race as mounted() above — await the
        // settings fetch before anything reads user_settings again.
        await this.settingStore.startSettingsFetch();
      } catch {
        this.isProfileError = true;
      } finally {
        this.isLoadingProfile = false;
      }
    },
  },
});
</script>

