import catalog from 'src/components/SettingsAssistant/settings-catalog.json';

export interface CatalogEntry {
  setting_key: string;
  scope: 'org' | 'sub_org' | 'doc_type' | string;
  app_path: string;
  breadcrumb: string[];
  anchor: string;
  label_key: string;
  synonyms?: string[];
}

export interface IndexedSetting {
  entry: CatalogEntry;
  label: string;
  breadcrumb: string[];
  labelWords: string[];
  pathWords: string[];
  synonymWords: string[];
}

export interface SettingSearchHit {
  entry: CatalogEntry;
  label: string;
  breadcrumb: string[];
  score: number;
}

export const SETTINGS_CATALOG = catalog as CatalogEntry[];
export const DOC_TYPE_PLACEHOLDER = '{doc_type_key}';
const MIN_QUERY_LENGTH = 2;

export function normalize(text: string): string {
  return text
    .toLowerCase()
    .replace(/ß/g, 'ss')
    .replace(/ä/g, 'ae')
    .replace(/ö/g, 'oe')
    .replace(/ü/g, 'ue')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '');
}

function words(text: string): string[] {
  return normalize(text)
    .split(/[^a-z0-9]+/)
    .filter(Boolean);
}

export function buildSettingsIndex(
  t: (key: string) => string,
  entries: CatalogEntry[] = SETTINGS_CATALOG,
): IndexedSetting[] {
  return entries.map((entry) => {
    const label = t(entry.label_key);
    const breadcrumb = entry.breadcrumb.slice(1).map((crumb) => t(crumb));
    return {
      entry,
      label,
      breadcrumb,
      labelWords: words(`${label} ${entry.setting_key.replace(/_/g, ' ')}`),
      pathWords: words(breadcrumb.join(' ')),
      synonymWords: words((entry.synonyms ?? []).join(' ')),
    };
  });
}

// Allows one typo for tokens of five or more characters.
function withinOneEdit(a: string, b: string): boolean {
  if (Math.abs(a.length - b.length) > 1) return false;
  let i = 0;
  let j = 0;
  let edits = 0;
  while (i < a.length && j < b.length) {
    if (a[i] === b[j]) {
      i++;
      j++;
      continue;
    }
    if (++edits > 1) return false;
    if (a.length > b.length) i++;
    else if (b.length > a.length) j++;
    else {
      i++;
      j++;
    }
  }
  return edits + (a.length - i) + (b.length - j) <= 1;
}

function tokenScore(token: string, candidates: string[]): number {
  let best = 0;
  for (const word of candidates) {
    if (word === token) return 3;
    if (word.startsWith(token)) best = Math.max(best, 2);
    else if (token.length >= 4 && word.includes(token)) best = Math.max(best, 1.5);
    else if (token.length >= 5 && withinOneEdit(token, word.slice(0, token.length)))
      best = Math.max(best, 1);
  }
  return best;
}

export function searchSettings(
  index: IndexedSetting[],
  query: string,
  limit = 8,
): SettingSearchHit[] {
  const tokens = words(query);
  if (normalize(query).trim().length < MIN_QUERY_LENGTH || !tokens.length) return [];

  const hits: SettingSearchHit[] = [];
  for (const item of index) {
    let score = 0;
    let matchedAll = true;
    for (const token of tokens) {
      const s = Math.max(
        tokenScore(token, item.labelWords) * 2,
        tokenScore(token, item.synonymWords) * 1.5,
        tokenScore(token, item.pathWords),
      );
      if (!s) {
        matchedAll = false;
        break;
      }
      score += s;
    }
    if (!matchedAll) continue;
    if (normalize(item.label).startsWith(normalize(query).trim())) score += 4;
    hits.push({ entry: item.entry, label: item.label, breadcrumb: item.breadcrumb, score });
  }
  return hits
    .sort((a, b) => b.score - a.score || a.label.localeCompare(b.label))
    .slice(0, limit);
}

// Doc-type settings need a concrete doc type: reuse the one in the current route, else open the list.
export function resolveSettingPath(
  entry: CatalogEntry,
  currentDocType?: string,
): { path: string; exact: boolean } {
  if (!entry.app_path.includes(DOC_TYPE_PLACEHOLDER)) {
    return { path: entry.app_path, exact: true };
  }
  if (currentDocType) {
    return {
      path: entry.app_path.replace(DOC_TYPE_PLACEHOLDER, encodeURIComponent(currentDocType)),
      exact: true,
    };
  }
  return { path: '/settings/document-types', exact: false };
}
