/* eslint-disable no-control-regex -- Security contract explicitly rejects ASCII control characters. */
import { VIDEO_ORIGIN } from './pageVideos';

/** CORE-6111 — an explainer video attached to a documentation source. */
export interface DocsVideo {
  title: string;
  url: string;
}

const MAX_VIDEOS_PER_SOURCE = 3;
const MAX_URL_CHARS = 300;
const MAX_TITLE_CHARS = 120;
const UNSAFE_RAW_CHARS = /[\\\x00-\x1f\x7f]/;
// The explainer videos live under settings-assistant/<page key>/v<N>/<locale>.mp4 on the
// CDN bucket; any other object on that host is not a video of ours (mirrors the API).
const VIDEO_PATH =
  /^\/settings-assistant\/[A-Za-z0-9_-]{1,80}\/v\d{1,4}\/[A-Za-z]{2}(?:-[A-Za-z]{2})?\.mp4$/;
const UNSAFE_TITLE_CHARS = /[<>\\\x00-\x1f\x7f]/;

/** https mp4 on exactly the DocBits video CDN, nothing else (mirrors the API). */
export function isAllowedDocsVideoUrl(url: unknown): url is string {
  if (typeof url !== 'string' || !url || url.length > MAX_URL_CHARS) return false;
  if (UNSAFE_RAW_CHARS.test(url)) return false;
  // The RAW string must be the absolute CDN url: `new URL` also accepts `https:/host/x`,
  // which a browser resolves RELATIVE to the app's own origin for <video src>.
  if (!url.startsWith(`${VIDEO_ORIGIN}/`)) return false;
  let parsed: URL;
  try {
    parsed = new URL(url);
  } catch {
    return false;
  }
  if (parsed.origin !== VIDEO_ORIGIN || parsed.protocol !== 'https:') return false;
  if (parsed.username || parsed.password || parsed.port) return false;
  if (parsed.search || parsed.hash) return false;
  return VIDEO_PATH.test(parsed.pathname);
}

/** The valid `{title, url}` entries of a `source` frame's `videos`; anything else is dropped. */
export function parseDocsVideos(raw: unknown): DocsVideo[] {
  if (!Array.isArray(raw)) return [];
  const out: DocsVideo[] = [];
  const seen = new Set<string>();
  for (const item of raw) {
    if (out.length >= MAX_VIDEOS_PER_SOURCE) break;
    if (!item || typeof item !== 'object') continue;
    const { url, title } = item as { url?: unknown; title?: unknown };
    if (!isAllowedDocsVideoUrl(url) || seen.has(url)) continue;
    if (typeof title !== 'string') continue;
    const clean = title.replace(/\s+/g, ' ').trim();
    if (!clean || clean.length > MAX_TITLE_CHARS || UNSAFE_TITLE_CHARS.test(clean)) continue;
    seen.add(url);
    out.push({ title: clean, url });
  }
  return out;
}
