<template>
  <!-- q-dialog's own Escape/backdrop handling closes it; @hide lets the opener restore focus -->
  <q-dialog
    :model-value="modelValue"
    :data-test="`${testId}-lightbox`"
    @update:model-value="$emit('update:modelValue', $event)"
    @hide="$emit('hide')"
  >
    <q-card class="assistant-chat__lightbox-card">
      <header class="assistant-chat__lightbox-header">
        <div class="assistant-chat__lightbox-heading">
          <span v-if="image?.alt" class="assistant-chat__lightbox-title">{{
            image.alt
          }}</span>
        </div>
        <q-btn
          flat
          round
          dense
          size="sm"
          :aria-label="$t('settings_assistant_close')"
          :data-test="`${testId}-lightbox-close`"
          @click="$emit('update:modelValue', false)"
        >
          <Icon icon="mdi:close" width="18" height="18" />
        </q-btn>
      </header>
      <div class="assistant-chat__lightbox-body">
        <img
          v-if="image"
          :src="image.url"
          :alt="image.alt"
          class="assistant-chat__lightbox-img"
        />
      </div>
      <p v-if="image?.alt && caption" class="assistant-chat__lightbox-caption">
        {{ caption }}
      </p>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import { Icon } from '@iconify/vue';

export interface AssistantLightboxImage {
  url: string;
  alt: string;
}

export default defineComponent({
  name: 'AssistantImageLightbox',

  components: { Icon },

  props: {
    modelValue: {
      type: Boolean,
      default: false,
    },
    image: {
      type: Object as PropType<AssistantLightboxImage | null>,
      default: null,
    },
    caption: {
      type: String,
      default: '',
    },
    testId: {
      type: String,
      default: 'settings-assistant',
    },
  },

  emits: ['update:modelValue', 'hide'],
});
</script>

